input.command:
cd assets/fonts && node -e '
const fs=require("fs");
const css=fs.readFileSync("fonts.css","utf8");
const blocks=css.split("@font-face").slice(1);
let out="";
for(const b of blocks){
  if(!b.includes("U+0000-00FF")) continue;
  const fam=(b.match(/font-family: \x27([^\x27]+)\x27/)||[])[1];
  const w=(b.match(/font-weight: (\d+)/)||[])[1];
  const url=(b.match(/url\((https:[^)]+)\)/)||[])[1];
  const slug=fam.toLowerCase().replace(/ /g,"-")+"-"+w+".woff2";
  out+=`@font-face{font-family:"${fam}";font-style:normal;font-weight:${w};font-display:swap;src:url("${slug}") format("woff2")}\n`;
  fs.appendFileSync("downloads.txt",url+" "+slug+"\n");
}
fs.writeFileSync("local.css",out);
' && while read u f; do curl -s "$u" -o "$f"; done < downloads.txt && ls -la *.woff2 && cat local.css

