// ---------- SMALL 3D HELPERS ----------
export function mesh(geo, mat, x = 0, y = 0, z = 0) {
  const m = new THREE.Mesh(geo, mat);
  m.position.set(x, y, z);
  m.castShadow = true;
  m.receiveShadow = true;
  return m;
}

export function disposeObject(obj) {
  obj.traverse(o => {
    if (o.geometry) o.geometry.dispose();
    if (o.material) {
      if (Array.isArray(o.material)) o.material.forEach(m => m.dispose());
      else o.material.dispose();
    }
  });
}

export function makeTextSprite(text, color = '#5ce8d4', size = 0.5) {
  const c = document.createElement('canvas');
  c.width = 256; c.height = 64;
  const ctx = c.getContext('2d');
  ctx.font = 'bold 38px "Barlow Condensed", sans-serif';
  ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
  ctx.shadowColor = color; ctx.shadowBlur = 12;
  ctx.fillStyle = color;
  ctx.fillText(text, 128, 34);
  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  const mat = new THREE.SpriteMaterial({ map: tex, transparent: true, depthWrite: false, opacity: 0.95 });
  const sprite = new THREE.Sprite(mat);
  sprite.scale.set(size * 4, size, 1);
  return sprite;
}

// ============ PROCEDURAL AUDIO (WebAudio, no external assets) ============
class AudioEngine {
  constructor() {
    this.ctx = null;
    this.master = null;
    this.volume = 0.65;
    this.muted = false;
    this.started = false;
    this.ambient = null;
    this.noiseBuf = null;
  }

  init() {
    if (this.ctx) return;
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return;
    this.ctx = new AC();
    this.master = this.ctx.createGain();
    this.master.gain.value = this.volume;
    this.master.connect(this.ctx.destination);

    const len = this.ctx.sampleRate * 2;
    const buf = this.ctx.createBuffer(1, len, this.ctx.sampleRate);
    const d = buf.getChannelData(0);
    for (let i = 0; i < len; i++) d[i] = Math.random() * 2 - 1;
    this.noiseBuf = buf;
  }

  resume() {
    this.init();
    if (!this.ctx) return;
    if (this.ctx.state === 'suspended') this.ctx.resume();
    this.started = true;
  }

  setVolume(v) {
    this.volume = v;
    if (this.master) this.master.gain.value = this.muted ? 0 : v;
  }

  toggleMute() {
    this.muted = !this.muted;
    if (this.master) this.master.gain.value = this.muted ? 0 : this.volume;
    return this.muted;
  }

  now() { return this.ctx ? this.ctx.currentTime : 0; }

  noise(dur = 0.1, filterFreq = 1200, type = 'lowpass', gain = 0.3, q = 0.8, delay = 0) {
    if (!this.ctx || this.muted) return null;
    const t = this.now() + delay;
    const src = this.ctx.createBufferSource();
    src.buffer = this.noiseBuf;
    src.loop = true;
    const f = this.ctx.createBiquadFilter();
    f.type = type; f.frequency.value = filterFreq; f.Q.value = q;
    const g = this.ctx.createGain();
    g.gain.setValueAtTime(0, t);
    g.gain.linearRampToValueAtTime(gain, t + 0.004);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    src.connect(f); f.connect(g); g.connect(this.master);
    src.start(t); src.stop(t + dur + 0.02);
    return { src, f, g, t };
  }

  tone(freq = 440, dur = 0.1, type = 'sine', gain = 0.2, delay = 0, slideTo = null) {
    if (!this.ctx || this.muted) return;
    const t = this.now() + delay;
    const o = this.ctx.createOscillator();
    o.type = type;
    o.frequency.setValueAtTime(freq, t);
    if (slideTo) o.frequency.exponentialRampToValueAtTime(slideTo, t + dur);
    const g = this.ctx.createGain();
    g.gain.setValueAtTime(0, t);
    g.gain.linearRampToValueAtTime(gain, t + 0.005);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    o.connect(g); g.connect(this.master);
    o.start(t); o.stop(t + dur + 0.02);
  }

  shot(weapon) {
    if (!this.ctx) return;
    if (weapon === 'sniper') {
      this.noise(0.34, 1400, 'lowpass', 0.55);
      this.tone(70, 0.28, 'sine', 0.5, 0, 34);
      this.noise(0.09, 4200, 'highpass', 0.22);
    } else if (weapon === 'shotgun') {
      this.noise(0.3, 900, 'lowpass', 0.55);
      this.tone(58, 0.24, 'sine', 0.5, 0, 30);
    } else if (weapon === 'smg') {
      this.noise(0.075, 2000, 'bandpass', 0.3, 1.4);
      this.tone(110, 0.06, 'square', 0.12, 0, 60);
    } else if (weapon === 'pistol') {
      this.noise(0.09, 1800, 'bandpass', 0.3, 1.2);
      this.tone(120, 0.07, 'triangle', 0.15, 0, 60);
    } else {
      this.noise(0.13, 1700, 'lowpass', 0.4);
      this.tone(90, 0.1, 'triangle', 0.25, 0, 45);
      this.noise(0.05, 5000, 'highpass', 0.1);
    }
  }

  hit(head = false) {
    this.tone(head ? 1650 : 1150, 0.045, 'square', 0.09);
    if (head) this.tone(2200, 0.05, 'sine', 0.06, 0.03);
  }

  kill() {
    this.tone(880, 0.07, 'triangle', 0.1);
    this.tone(1320, 0.09, 'triangle', 0.08, 0.05);
  }

  explosion() {
    this.noise(0.8, 420, 'lowpass', 0.65);
    this.tone(46, 0.7, 'sine', 0.55, 0, 22);
    this.noise(0.16, 3000, 'highpass', 0.15);
  }

  reload() {
    this.noise(0.03, 3800, 'bandpass', 0.12, 2);
    this.tone(320, 0.03, 'square', 0.04, 0.25);
    this.tone(260, 0.04, 'square', 0.05, 0.62);
    this.noise(0.03, 2600, 'bandpass', 0.1, 2, 0.9);
  }

  footstep(running = false) {
    this.noise(0.055, running ? 500 : 380, 'lowpass', running ? 0.09 : 0.05);
  }

  hurt() {
    this.tone(160, 0.12, 'sawtooth', 0.08, 0, 90);
    this.noise(0.1, 700, 'lowpass', 0.12);
  }

  ui() {
    this.tone(720, 0.035, 'square', 0.035);
    this.tone(980, 0.03, 'square', 0.025, 0.02);
  }

  error() {
    this.tone(220, 0.12, 'square', 0.06);
    this.tone(160, 0.16, 'square', 0.06, 0.08);
  }

  capture() {
    this.tone(520, 0.14, 'triangle', 0.1);
    this.tone(660, 0.16, 'triangle', 0.09, 0.1);
    this.tone(880, 0.24, 'triangle', 0.09, 0.22);
  }

  spawn() {
    this.tone(300, 0.2, 'sine', 0.09, 0, 620);
  }

  victory() {
    [523, 659, 784, 1046].forEach((f, i) => this.tone(f, 0.6, 'triangle', 0.09, i * 0.13));
    this.tone(130, 0.9, 'sine', 0.12, 0);
  }

  defeat() {
    [392, 330, 262, 196].forEach((f, i) => this.tone(f, 0.55, 'triangle', 0.08, i * 0.16));
  }

  startAmbient() {
    if (!this.ctx || this.ambient) return;
    const t = this.now();
    const g = this.ctx.createGain();
    g.gain.value = 0; g.gain.linearRampToValueAtTime(0.045, t + 2);
    const f = this.ctx.createBiquadFilter();
    f.type = 'lowpass'; f.frequency.value = 240;
    const o1 = this.ctx.createOscillator(); o1.type = 'sawtooth'; o1.frequency.value = 48;
    const o2 = this.ctx.createOscillator(); o2.type = 'sine'; o2.frequency.value = 55.5;
    const wind = this.ctx.createBufferSource();
    wind.buffer = this.noiseBuf; wind.loop = true;
    const wf = this.ctx.createBiquadFilter(); wf.type = 'bandpass'; wf.frequency.value = 420; wf.Q.value = 0.4;
    const wg = this.ctx.createGain(); wg.gain.value = 0.12;
    o1.connect(f); o2.connect(f); wind.connect(wf); wf.connect(wg); wg.connect(f);
    f.connect(g); g.connect(this.master);
    o1.start(t); o2.start(t); wind.start(t);
    this.ambient = { g, o1, o2, wind };
  }
}

export const audio = new AudioEngine();

// ============ WORLD: NEON HARBOR ============
import * as THREE from 'three';
import {
  asphaltTexture, concreteTexture, metalPanelTexture, containerTexture, crateTexture,
  hazardTexture, neonTexture, graffitiTexture, warningTexture, makeTextSprite,
  makeAABB, rayAABB, seeded, clamp
} from './util.js';
import { CONTROL_POINTS } from './config.js';

const TEAM_COLORS = { blue: 0x5ce8d4, red: 0xff5f52, neutral: 0xd8e8e6 };

export class World {
  constructor(scene, renderer) {
    this.scene = scene;
    this.renderer = renderer;
    this.colliders = [];
    this.group = new THREE.Group();
    this.scene.add(this.group);
    this.captureVisuals = {};
    this.materials = {};
    this.time = 0;
    this.dust = null;
    this.lights = [];
    this.build();
  }

  build() {
    this.buildMaterials();
    this.buildSky();
    this.buildLights();
    this.buildGround();
    this.buildPerimeter();
    this.buildWarehouse(-1);
    this.buildWarehouse(1);
    this.buildCenter();
    this.buildContainers();
    this.buildCatwalk();
    this.buildDetails();
    this.buildCapturePoints();
    this.buildSkyline();
    this.buildDust();
  }

  buildMaterials() {
    const std = (opts) => new THREE.MeshStandardMaterial(opts);
    this.materials.concrete = std({ map: concreteTexture(), color: 0x8b9292, roughness: 0.92, metalness: 0.04 });
    this.materials.concreteDark = std({ map: concreteTexture(), color: 0x555e60, roughness: 0.95, metalness: 0.03 });
    this.materials.asphalt = std({ map: asphaltTexture(), color: 0x7d8688, roughness: 0.88, metalness: 0.12 });
    this.materials.metal = std({ map: metalPanelTexture(), color: 0x7e8a8e, roughness: 0.55, metalness: 0.55 });
    this.materials.metalDark = std({ map: metalPanelTexture(), color: 0x3b4448, roughness: 0.5, metalness: 0.65 });
    this.materials.rust = std({ map: metalPanelTexture(), color: 0x8a5840, roughness: 0.8, metalness: 0.4 });
    this.materials.crate = std({ map: crateTexture(), color: 0x9b8a6c, roughness: 0.9, metalness: 0.02 });
    this.materials.hazard = std({ map: hazardTexture(), roughness: 0.7, metalness: 0.2 });
    this.materials.dark = std({ color: 0x0c1114, roughness: 0.8, metalness: 0.3 });
    this.materials.rubber = std({ color: 0x111416, roughness: 1 });
    this.materials.glass = new THREE.MeshStandardMaterial({ color: 0x5f9ba0, roughness: 0.12, metalness: 0.8, transparent: true, opacity: 0.5 });
    this.materials.neonCyan = new THREE.MeshBasicMaterial({ color: 0x5ce8d4 });
    this.materials.neonAmber = new THREE.MeshBasicMaterial({ color: 0xffb454 });
    this.materials.neonPink = new THREE.MeshBasicMaterial({ color: 0xff4d8d });
    this.materials.rail = std({ color: 0x9aa6a5, roughness: 0.4, metalness: 0.8 });
    this.containerMats = {
      rust: std({ map: containerTexture('rust'), roughness: 0.72, metalness: 0.35 }),
      teal: std({ map: containerTexture('teal'), roughness: 0.7, metalness: 0.35 }),
      blue: std({ map: containerTexture('blue'), roughness: 0.7, metalness: 0.4 }),
      yellow: std({ map: containerTexture('yellow'), roughness: 0.75, metalness: 0.3 }),
      grey: std({ map: containerTexture('grey'), roughness: 0.7, metalness: 0.45 })
    };
  }

  // ---------- helpers ----------
  addBox(w, h, d, x, y, z, mat, opts = {}) {
    const geo = new THREE.BoxGeometry(w, h, d);
    const m = new THREE.Mesh(geo, mat);
    m.position.set(x, y, z);
    if (opts.rotY) m.rotation.y = opts.rotY;
    m.castShadow = opts.shadow !== false;
    m.receiveShadow = true;
    this.group.add(m);
    if (opts.collide !== false) {
      const swap = opts.rotY && Math.abs(Math.round(Math.sin(opts.rotY))) === 1;
      this.colliders.push(makeAABB(x, y, z, swap ? d : w, h, swap ? w : d, opts.tag || 'solid'));
    }
    return m;
  }

  addDecal(w, h, x, y, z, rotY, texture, opacity = 1) {
    const mat = new THREE.MeshBasicMaterial({ map: texture, transparent: true, opacity, side: THREE.DoubleSide, depthWrite: false, blending: THREE.AdditiveBlending });
    const m = new THREE.Mesh(new THREE.PlaneGeometry(w, h), mat);
    m.position.set(x, y, z);
    m.rotation.y = rotY;
    this.group.add(m);
    return m;
  }

  addTrim(w, h, d, x, y, z, mat = this.materials.metalDark, rotY = 0) {
    const m = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), mat);
    m.position.set(x, y, z);
    m.rotation.y = rotY;
    m.castShadow = false; m.receiveShadow = true;
    this.group.add(m);
    return m;
  }

  // ---------- sky ----------
  buildSky() {
    const geo = new THREE.SphereGeometry(260, 32, 24);
    const mat = new THREE.ShaderMaterial({
      side: THREE.BackSide,
      depthWrite: false,
      uniforms: {
        top: { value: new THREE.Color(0x050d18) },
        mid: { value: new THREE.Color(0x14323d) },
        horizon: { value: new THREE.Color(0xc06a48) },
        sunDir: { value: new THREE.Vector3(0.62, 0.12, -0.78).normalize() },
        sunColor: { value: new THREE.Color(0xffb26b) }
      },
      vertexShader: `varying vec3 vDir; void main(){ vDir = normalize(position); gl_Position = projectionMatrix * modelViewMatrix * vec4(position,1.0); }`,
      fragmentShader: `
        varying vec3 vDir; uniform vec3 top; uniform vec3 mid; uniform vec3 horizon; uniform vec3 sunDir; uniform vec3 sunColor;
        void main(){
          float h = clamp(vDir.y*1.35+0.06, 0.0, 1.0);
          vec3 col = mix(horizon, mid, smoothstep(0.0,0.34,h));
          col = mix(col, top, smoothstep(0.25,0.9,h));
          float s = max(dot(normalize(vDir), sunDir), 0.0);
          col += sunColor * pow(s, 90.0) * 1.4;
          col += sunColor * pow(s, 8.0) * 0.22;
          float band = sin(vDir.y*140.0)*0.5+0.5;
          col += vec3(0.02,0.03,0.035)*band*0.15;
          gl_FragColor = vec4(col,1.0);
        }`
    });
    const sky = new THREE.Mesh(geo, mat);
    sky.frustumCulled = false;
    this.scene.add(sky);
    this.sky = sky;
    this.scene.fog = new THREE.FogExp2(0x18292e, 0.0085);
  }

