  buildTruck(x, z, rotY) {
    const g = new THREE.Group();
    g.position.set(x, 0, z); g.rotation.y = rotY;
    const cab = new THREE.Mesh(new THREE.BoxGeometry(2.5, 2.4, 2.4), this.materials.rust);
    cab.position.set(0, 1.35, 3.4); cab.castShadow = true; cab.receiveShadow = true; g.add(cab);
    const win = new THREE.Mesh(new THREE.BoxGeometry(2.1, 0.8, 0.1), this.materials.glass);
    win.position.set(0, 1.9, 4.62); g.add(win);
    const trailer = new THREE.Mesh(new THREE.BoxGeometry(2.55, 2.7, 6.2), this.containerMats.grey);
    trailer.position.set(0, 1.55, -0.4); trailer.castShadow = true; trailer.receiveShadow = true; g.add(trailer);
    for (const [wx, wz] of [[-1.2, 3.2], [1.2, 3.2], [-1.2, -2.2], [1.2, -2.2]]) {
      const wheel = new THREE.Mesh(new THREE.CylinderGeometry(0.5, 0.5, 0.32, 14), this.materials.rubber);
      wheel.rotation.z = Math.PI / 2; wheel.position.set(wx, 0.5, wz); g.add(wheel);
    }
    this.group.add(g);
    const swap = Math.abs(Math.round(Math.sin(rotY))) === 1;
    this.colliders.push(makeAABB(x, 1.3, z, swap ? 7.4 : 2.7, 2.8, swap ? 2.7 : 7.4, 'vehicle'));
  }

  buildPipe(x, z, rot) {
    const g = new THREE.Group();
    g.position.set(x, 0, z); g.rotation.y = rot;
    for (let i = 0; i < 3; i++) {
      const p = new THREE.Mesh(new THREE.CylinderGeometry(0.62, 0.62, 2.6, 16), this.materials.rust);
      p.rotation.z = Math.PI / 2; p.position.set(-0.7 + i * 0.7, 0.65 + (i === 1 ? 1.15 : 0), 0);
      p.castShadow = true; p.receiveShadow = true; g.add(p);
    }
    this.group.add(g);
    this.colliders.push(makeAABB(x, 0.9, z, Math.abs(Math.cos(rot)) > 0.5 ? 2.6 : 2.2, 1.8, Math.abs(Math.cos(rot)) > 0.5 ? 2.2 : 2.6, 'pipe'));
  }

  buildContainers() {
    const list = [
      [-13.5, 23, 0, 'teal', 2], [13.5, 23, 0, 'blue', 1], [-13.5, 15.5, 0, 'rust', 1],
      [13.5, 15.5, 0, 'yellow', 2], [-20.5, -14, 0, 'blue', 1], [20.5, -14, 0, 'rust', 2],
      [-7, -18, 90, 'grey', 1], [7, -18, 90, 'teal', 1], [0, 22.5, 90, 'yellow', 1],
      [-38, 28, 0, 'rust', 1], [38, 28, 90, 'blue', 1], [-38, -30, 90, 'grey', 1], [38, -29, 0, 'teal', 1],
      [-24, -37, 0, 'yellow', 2], [24, -37, 90, 'grey', 1]
    ];
    for (const [x, z, r, color, levels] of list) this.addContainer(x, z, r, color, levels);

    // crate staircases to climb containers
    this.addCrate(-17.6, 0.45, 23, 0.9);
    this.addCrate(-16.4, 1.35, 23, 0.9);
    this.addCrate(-16.4, 0.45, 21.9, 0.9);
    this.addCrate(17.7, 0.45, 23, 0.9);
    this.addCrate(16.5, 1.35, 23, 0.9);
    this.addCrate(16.5, 0.45, 21.9, 0.9);
    this.addCrate(24.2, 0.45, -14, 0.9);
    this.addCrate(23, 1.35, -14, 0.9);
  }

  addContainer(x, z, rotY, color, levels = 1) {
    const h = 2.6 * levels;
    const swap = Math.abs(Math.round(Math.sin(rotY))) === 1;
    const w = swap ? 2.44 : 6.06;
    const d = swap ? 6.06 : 2.44;
    const m = new THREE.Mesh(new THREE.BoxGeometry(6.06, h, 2.44), this.containerMats[color] || this.containerMats.rust);
    m.position.set(x, h / 2, z);
    m.rotation.y = rotY;
    m.castShadow = true; m.receiveShadow = true;
    this.group.add(m);
    // corner castings
    for (const sx of [-1, 1]) for (const sz of [-1, 1]) {
      const c = new THREE.Mesh(new THREE.BoxGeometry(0.22, 0.22, 0.22), this.materials.metalDark);
      c.position.set(x + Math.cos(rotY) * sx * 2.9 - Math.sin(rotY) * sz * 1.1, h - 0.12, z + Math.sin(rotY) * sx * 2.9 + Math.cos(rotY) * sz * 1.1);
      this.group.add(c);
    }
    // door lines on ends
    const door = new THREE.Mesh(new THREE.PlaneGeometry(0.04, h - 0.4), this.materials.metalDark);
    door.position.set(x + Math.cos(rotY) * 3.03, h / 2, z + Math.sin(rotY) * 3.03);
    door.rotation.y = rotY + Math.PI / 2;
    this.group.add(door);
    this.colliders.push(makeAABB(x, h / 2, z, w, h, d, 'container'));
  }

  addCrate(x, y, z, size) {
    const m = this.addBox(size, size, size, x, y, z, this.materials.crate, { tag: 'crate' });
    return m;
  }

  addBarrier(x, z, rotY) {
    const swap = Math.abs(Math.round(Math.sin(rotY * Math.PI / 180))) === 1;
    this.addBox(3.4, 1.25, 0.5, x, 0.63, z, this.materials.concrete, { rotY: rotY * Math.PI / 180, tag: 'barrier' });
    this.addTrim(3.5, 0.1, 0.56, x, 1.28, z, this.materials.hazard, rotY * Math.PI / 180);
  }

  addStairs(x, z, axis, width, steps, totalHeight, stepDepth, rotY = 0, tag = 'stairs') {
    // stairs ascend along -z when rotY=0, toward +z when rotY=PI
    const stepH = totalHeight / steps;
    const dir = Math.abs(rotY) > 1 ? 1 : -1;
    for (let i = 0; i < steps; i++) {
      const h = stepH * (i + 1);
      const zz = z + dir * stepDepth * i;
      const xx = x;
      this.addBox(width, h, stepDepth, xx, h / 2, zz, i % 3 === 0 ? this.materials.metal : this.materials.metalDark, { tag: 'step', shadow: i === steps - 1 });
    }
    // side rails
    for (const s of [-1, 1]) {
      const rail = new THREE.Mesh(new THREE.BoxGeometry(0.07, 0.07, steps * stepDepth + 0.4), this.materials.rail);
      rail.position.set(x + s * width / 2, totalHeight + 0.55, z + dir * (steps * stepDepth - stepDepth) / 2);
      rail.rotation.x = Math.atan2(totalHeight, steps * stepDepth) * (dir > 0 ? -1 : 1);
      this.group.add(rail);
    }
  }

  buildCatwalk() {
    const y = 3.5, z = -25.5, len = 66, w = 3.6;
    this.addBox(len, 0.35, w, 0, y, z, this.materials.metal, { tag: 'catwalk' });
    // underside supports
    for (let x = -30; x <= 30; x += 10) {
      this.addTrim(0.35, y, 0.35, x, y / 2, z - 1.4, this.materials.metalDark);
      this.addTrim(0.35, y, 0.35, x, y / 2, z + 1.4, this.materials.metalDark);
    }
    // railings (two sides), leave gaps at stairs x=±29
    for (const side of [-1, 1]) {
      for (const [x0, x1] of [[-33, -31], [-29, 29], [31, 33]]) {
        if (x1 <= x0) continue;
        const cx = (x0 + x1) / 2, l = x1 - x0;
        this.addTrim(l, 0.08, 0.08, cx, y + 1.15, z + side * (w / 2), this.materials.rail);
        this.addTrim(l, 0.08, 0.08, cx, y + 0.55, z + side * (w / 2), this.materials.rail);
        const posts = Math.max(2, Math.round(l / 3));
        for (let i = 0; i <= posts; i++) {
          this.addTrim(0.07, 1.2, 0.07, x0 + (l * i) / posts, y + 0.6, z + side * (w / 2), this.materials.rail);
        }
      }
    }
    // neon strips on catwalk edge
    for (const side of [-1, 1]) {
      const strip = new THREE.Mesh(new THREE.BoxGeometry(len, 0.05, 0.05), side === -1 ? this.materials.neonAmber : this.materials.neonCyan);
      strip.position.set(0, y - 0.18, z + side * (w / 2));
      this.group.add(strip);
    }
    // stairs down at both ends toward center
    this.addStairs(-31, z + 2.2, 'z', 2.6, 13, y, 0.55, 0, 'stairs');
    this.addStairs(31, z + 2.2, 'z', 2.6, 13, y, 0.55, 0, 'stairs');
    // platform at both ends
    this.addBox(5, 0.35, 5, -31, y, z, this.materials.metal, { tag: 'catwalk' });
    this.addBox(5, 0.35, 5, 31, y, z, this.materials.metal, { tag: 'catwalk' });

    // hanging lights under catwalk
    for (let x = -24; x <= 24; x += 12) {
      const lamp = new THREE.Mesh(new THREE.BoxGeometry(1.2, 0.15, 0.3), this.materials.neonAmber);
      lamp.position.set(x, y - 0.6, z);
      this.group.add(lamp);
    }
  }

  buildDetails() {
    // crane at NE
    this.buildCrane(37, -36);
    // floodlight poles
    for (const [x, z] of [[-42, 38], [42, 38], [-42, -38], [42, -38], [-5, 0]]) {
      this.buildLightPole(x, z);
    }
    // guard shack south-west
    this.addBox(5, 3.2, 4.4, -37, 1.6, 37, this.materials.metalDark, { tag: 'shack' });
    this.addBox(5.6, 0.3, 5, -37, 3.35, 37, this.materials.metal, { tag: 'roof' });
    this.addBox(2.6, 1.1, 0.05, -37, 1.9, 34.78, this.materials.glass, { collide: false });
    this.addDecal(4, 1.4, -37, 3.9, 34.7, 0, neonTexture('GATE 3', '#ffb454'), 1);
    // jersey barriers along lanes
    for (const [x, z, r] of [[-33, 20, 90], [-33, -6, 90], [33, 20, 90], [33, -6, 90], [0, 32, 0], [0, 30, 0]]) {
      this.addBarrier(x, z, r);
    }
    // north lane cover
    for (const [x, z] of [[-6, -32], [6, -32], [-18, -30], [18, -30]]) this.addBarrier(x, z, 0);
    // south approach
    for (const [x, z] of [[-17, 29], [17, 29], [0, 27]]) this.addBarrier(x, z, 0);
    // scattered crates
    for (const [x, z, s] of [[-8, 34, 1.1], [9, 34, 0.9], [-22, 34, 1.3], [23, 34, 1.0], [-28, -35, 1.0], [28, -35, 1.2]]) {
      this.addCrate(x, s / 2, z, s);
    }
    // pipes near walls
    // antenna tower
    const tower = new THREE.Group();
    tower.position.set(-43, 0, -40);
    for (let i = 0; i < 3; i++) {
      const leg = new THREE.Mesh(new THREE.CylinderGeometry(0.08, 0.12, 14, 5), this.materials.rail);
      leg.position.set(Math.cos(i * 2.1) * 0.8, 7, Math.sin(i * 2.1) * 0.8);
      leg.rotation.z = Math.cos(i * 2.1) * 0.06; leg.rotation.x = -Math.sin(i * 2.1) * 0.06;
      tower.add(leg);
    }
    const beacon = new THREE.Mesh(new THREE.SphereGeometry(0.18, 8, 8), this.materials.neonPink);
    beacon.position.y = 14.2; tower.add(beacon);
    this.group.add(tower);
    this.colliders.push(makeAABB(-43, 7, -40, 2, 14, 2, 'tower'));

    // ambience: crates near spawn
    this.addBox(4, 1, 1, -6, 0.5, 44, this.materials.concrete, { tag: 'cover' });
    this.addBox(4, 1, 1, 6, 0.5, -44, this.materials.concrete, { tag: 'cover' });
  }

  buildCrane(x, z) {
    const g = new THREE.Group();
    g.position.set(x, 0, z);
    const base = new THREE.Mesh(new THREE.BoxGeometry(5, 1.2, 5), this.materials.metalDark);
    base.position.y = 0.6; base.castShadow = true; g.add(base);
    const towerH = 20;
    for (const [sx, sz] of [[-1.4, -1.4], [1.4, -1.4], [1.4, 1.4], [-1.4, 1.4]]) {
      const leg = new THREE.Mesh(new THREE.BoxGeometry(0.32, towerH, 0.32), this.materials.rust);
      leg.position.set(sx, 1.2 + towerH / 2, sz); leg.castShadow = true; g.add(leg);
    }
    for (let i = 0; i < 7; i++) {
      const brace = new THREE.Mesh(new THREE.BoxGeometry(3.6, 0.1, 0.1), this.materials.rail);
      brace.position.set(0, 3 + i * 2.6, 0); brace.rotation.z = i % 2 ? 0.5 : -0.5; g.add(brace);
      const brace2 = brace.clone(); brace2.rotation.z = -brace.rotation.z; g.add(brace2);
    }
    const cab = new THREE.Mesh(new THREE.BoxGeometry(3.4, 2.2, 3), this.materials.metal);
    cab.position.set(0, towerH + 1.4, 0); cab.castShadow = true; g.add(cab);
    const cabWin = new THREE.Mesh(new THREE.BoxGeometry(3.0, 1, 0.1), this.materials.glass);
    cabWin.position.set(0, towerH + 1.6, 1.51); g.add(cabWin);
    const jib = new THREE.Mesh(new THREE.BoxGeometry(24, 0.45, 0.6), this.materials.metal);
    jib.position.set(-7, towerH + 2.4, 0); jib.castShadow = true; g.add(jib);
    const counter = new THREE.Mesh(new THREE.BoxGeometry(5, 0.45, 0.7), this.materials.metal);
    counter.position.set(6.5, towerH + 2.4, 0); g.add(counter);
    const cable = new THREE.Mesh(new THREE.CylinderGeometry(0.03, 0.03, 12, 4), this.materials.rail);
    cable.position.set(-15, towerH - 3.8, 0); g.add(cable);
    const hook = new THREE.Mesh(new THREE.BoxGeometry(0.8, 1.2, 0.8), this.materials.hazard);
    hook.position.set(-15, towerH - 10, 0); g.add(hook);
    const light = new THREE.Mesh(new THREE.SphereGeometry(0.22, 8, 8), this.materials.neonPink);
    light.position.set(-18.5, towerH + 2.7, 0); g.add(light);
    this.group.add(g);
    this.colliders.push(makeAABB(x, 1.5, z, 5, 3, 5, 'crane'));
  }

  buildLightPole(x, z) {
    const pole = new THREE.Mesh(new THREE.CylinderGeometry(0.11, 0.16, 9, 6), this.materials.rail);
    pole.position.set(x, 4.5, z); pole.castShadow = true; this.group.add(pole);
    const arm = new THREE.Mesh(new THREE.BoxGeometry(2.2, 0.12, 0.12), this.materials.rail);
    arm.position.set(x, 8.9, z); this.group.add(arm);
    const lamp = new THREE.Mesh(new THREE.BoxGeometry(1.4, 0.18, 0.4), this.materials.neonAmber);
    lamp.position.set(x, 8.75, z); this.group.add(lamp);
    const cone = new THREE.Mesh(new THREE.ConeGeometry(2.2, 1.2, 16, 1, true), new THREE.MeshBasicMaterial({ color: 0xffc27a, transparent: true, opacity: 0.04, side: THREE.DoubleSide, depthWrite: false, blending: THREE.AdditiveBlending }));
    cone.position.set(x, 8.1, z); cone.rotation.x = Math.PI;
    this.group.add(cone);
    this.colliders.push(makeAABB(x, 4.5, z, 0.5, 9, 0.5, 'pole'));
  }

  buildCapturePoints() {
    for (const p of CONTROL_POINTS) {
      const g = new THREE.Group();
      g.position.set(p.x, 0, p.z);
      const ringMat = new THREE.MeshBasicMaterial({ color: 0xd8e8e6, transparent: true, opacity: 0.55, side: THREE.DoubleSide, depthWrite: false });
      const ring = new THREE.Mesh(new THREE.RingGeometry(p.r - 0.25, p.r, 64), ringMat);
      ring.rotation.x = -Math.PI / 2; ring.position.y = 0.03; g.add(ring);
      const inner = new THREE.Mesh(new THREE.RingGeometry(p.r - 1.1, p.r - 1.0, 64), ringMat);
      inner.rotation.x = -Math.PI / 2; inner.position.y = 0.03; g.add(inner);
      const beamMat = new THREE.MeshBasicMaterial({ color: 0xd8e8e6, transparent: true, opacity: 0.06, side: THREE.DoubleSide, depthWrite: false, blending: THREE.AdditiveBlending });
      const beam = new THREE.Mesh(new THREE.CylinderGeometry(p.r * 0.72, p.r * 0.85, 12, 32, 1, true), beamMat);
      beam.position.y = 6; g.add(beam);
      const label = makeTextSprite(p.id, '#d8e8e6', 2.2);
      label.position.y = 3.3; g.add(label);
      this.group.add(g);
      this.captureVisuals[p.id] = { group: g, ring, inner, beam, label, ringMat, beamMat, ring2: inner.material };
    }
  }

  setCaptureState(id, team, progress = 0) {
    const v = this.captureVisuals[id];
    if (!v) return;
    const col = new THREE.Color(TEAM_COLORS[team] || TEAM_COLORS.neutral);
    v.ringMat.color.copy(col);
    v.beamMat.color.copy(col);
    v.beamMat.opacity = team === 'neutral' ? 0.035 : 0.10 + progress * 0.06;
    v.ringMat.opacity = team === 'neutral' ? 0.4 : 0.75;
    v.label.material.color.copy(col);
  }

  buildSkyline() {
    const rng = seeded;
    const winTex = (() => {
      const c = document.createElement('canvas');
      c.width = 64; c.height = 128;
      const ctx = c.getContext('2d');
      ctx.fillStyle = '#000'; ctx.fillRect(0, 0, 64, 128);
      for (let y = 5; y < 124; y += 7) {
        for (let x = 5; x < 60; x += 7) {
          if (rng() > 0.66) {
            ctx.fillStyle = rng() > 0.5 ? 'rgba(120,210,205,.85)' : 'rgba(255,180,84,.7)';
            ctx.fillRect(x, y, 3, 2);
          }
        }
      }
      const t = new THREE.CanvasTexture(c);
      t.colorSpace = THREE.SRGBColorSpace;
      t.wrapS = t.wrapT = THREE.RepeatWrapping;
      t.repeat.set(2, 2);
      return t;
    })();
    const bmat = new THREE.MeshStandardMaterial({ color: 0x0a141b, roughness: 0.9, metalness: 0.2, emissive: 0x2a6470, emissiveMap: winTex, emissiveIntensity: 0.55 });
    const bmat2 = new THREE.MeshStandardMaterial({ color: 0x0d1018, roughness: 0.9, emissive: 0xffb454, emissiveMap: winTex, emissiveIntensity: 0.35 });
    for (let i = 0; i < 34; i++) {
      const ang = (i / 34) * Math.PI * 2 + rng() * 0.12;
      const radius = 72 + rng() * 40;
      const x = Math.cos(ang) * radius, z = Math.sin(ang) * radius;
      const h = 14 + rng() * 48;
      const w = 8 + rng() * 11;
      const b = new THREE.Mesh(new THREE.BoxGeometry(w, h, w * 0.8), rng() > 0.72 ? bmat2 : bmat);
      b.position.set(x, h / 2 - 2, z);
      b.rotation.y = rng() * Math.PI;
      this.group.add(b);
      // roof beacon
      if (rng() > 0.7) {
        const dot = new THREE.Mesh(new THREE.SphereGeometry(0.25, 6, 6), this.materials.neonPink);
        dot.position.set(x, h, z);
        this.group.add(dot);
      }
    }
    // distant cranes silhouettes
    for (let i = 0; i < 5; i++) {
      const x = -90 + i * 45, z = -95 - rng() * 25;
      const mast = new THREE.Mesh(new THREE.BoxGeometry(2, 40 + i * 4, 2), this.materials.metalDark);
      mast.position.set(x, 20, z); this.group.add(mast);
      const jib = new THREE.Mesh(new THREE.BoxGeometry(34, 1.2, 1.2), this.materials.metalDark);
      jib.position.set(x - 8, 38 + i * 4, z); this.group.add(jib);
    }
  }

  buildDust() {
    const count = 700;
    const pos = new Float32Array(count * 3);
    const speed = new Float32Array(count);
    for (let i = 0; i < count; i++) {
      pos[i * 3] = (Math.random() - 0.5) * 96;
      pos[i * 3 + 1] = Math.random() * 22;
      pos[i * 3 + 2] = (Math.random() - 0.5) * 96;
      speed[i] = 0.15 + Math.random() * 0.5;
    }
    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.BufferAttribute(pos, 3));
    const mat = new THREE.PointsMaterial({ color: 0x9fd8d4, size: 0.055, transparent: true, opacity: 0.5, depthWrite: false, blending: THREE.AdditiveBlending, sizeAttenuation: true });
    const pts = new THREE.Points(geo, mat);
    this.scene.add(pts);
    this.dust = { pts, pos, speed, count };
  }

  // ---------- queries ----------
  raycast(origin, dir, maxDist = 200, ignoreTag = null) {
    let best = null, bestT = maxDist;
    for (const c of this.colliders) {
      if (ignoreTag && c.tag === ignoreTag) continue;
      const t = rayAABB(origin, dir, c, bestT);
      if (t !== null && t < bestT && t >= 0) {
        bestT = t; best = c;
      }
    }
    if (!best) return null;
    const point = new THREE.Vector3().copy(dir).multiplyScalar(bestT).add(origin);
    // approximate normal
    const eps = 0.002;
    let normal = new THREE.Vector3();
    const cx = (best.min.x + best.max.x) / 2, cy = (best.min.y + best.max.y) / 2, cz = (best.min.z + best.max.z) / 2;
    const dx = Math.abs(point.x - best.min.x), dx2 = Math.abs(best.max.x - point.x);
    const dy = Math.abs(point.y - best.min.y), dy2 = Math.abs(best.max.y - point.y);
    const dz = Math.abs(point.z - best.min.z), dz2 = Math.abs(best.max.z - point.z);
    const m = Math.min(dx, dx2, dy, dy2, dz, dz2);
    if (m === dx) normal.set(-1, 0, 0); else if (m === dx2) normal.set(1, 0, 0);
    else if (m === dy) normal.set(0, -1, 0); else if (m === dy2) normal.set(0, 1, 0);
    else if (m === dz) normal.set(0, 0, -1); else normal.set(0, 0, 1);
    return { dist: bestT, point, normal, collider: best };
  }

  lineOfSight(a, b) {
    const dir = new THREE.Vector3().subVectors(b, a);
    const dist = dir.length();
    if (dist < 0.01) return true;
    dir.multiplyScalar(1 / dist);
    const hit = this.raycast(a, dir, dist - 0.2);
    return !hit;
  }

  // horizontal ray check for bot avoidance
  blocked(x, z, dirX, dirZ, dist = 2.2) {
    const o = new THREE.Vector3(x, 1.0, z);
    const d = new THREE.Vector3(dirX, 0, dirZ).normalize();
    for (const c of this.colliders) {
      if (c.max.y < 0.4 || c.min.y > 2.2) continue;
      const t = rayAABB(o, d, c, dist);
      if (t !== null && t > 0.1) return true;
    }
    return false;
  }

  update(dt) {
    this.time += dt;
    // dust drift
    const d = this.dust;
    if (d) {
      for (let i = 0; i < d.count; i++) {
        d.pos[i * 3 + 1] += d.speed[i] * dt * 0.35;
        d.pos[i * 3] += Math.sin(this.time * 0.3 + i) * dt * 0.05;
        if (d.pos[i * 3 + 1] > 23) d.pos[i * 3 + 1] = 0;
      }
      d.pts.geometry.attributes.position.needsUpdate = true;
    }
    if (this.beaconRing) {
      this.beaconRing.rotation.z += dt * 0.6;
      this.beaconRing.material.opacity = 0.35 + Math.sin(this.time * 2) * 0.15;
    }
    if (this.beaconBeam) {
      this.beaconBeam.material.opacity = 0.09 + Math.sin(this.time * 1.4) * 0.04;
    }
    // blinking crane light
    for (const l of this.lights) l.intensity *= 0.999;
  }

  setQuality(level) {
    const high = level === 'high';
    const med = level === 'medium';
    this.sun.castShadow = level !== 'low';
    this.sun.shadow.mapSize.set(high ? 2048 : 1024, high ? 2048 : 1024);
    if (this.sun.shadow.map) { this.sun.shadow.map.dispose(); this.sun.shadow.map = null; }
    this.dust.pts.visible = !med && !high ? true : true;
    this.dust.pts.material.opacity = high ? 0.5 : 0.35;
    this.scene.fog.density = high ? 0.0075 : 0.0095;
  }
}

// ============ WEAPONS: FIRST-PERSON VIEWMODELS ============
import * as THREE from 'three';
import { WEAPONS, SKINS } from './config.js';

function mat(color, metalness = 0.6, roughness = 0.4, extra = {}) {
  return new THREE.MeshStandardMaterial({ color, metalness, roughness, ...extra });
}

export function buildWeaponModel(weaponId, skinId = 'camo_standard', operatorAccent = 0x5ce8d4) {
  const spec = WEAPONS[weaponId];
  const skin = SKINS[skinId] || SKINS.camo_standard;
  const c = skin.colors;
  const group = new THREE.Group();
  const bodyMat = mat(c.body, c.metalness, c.roughness, { emissive: new THREE.Color(c.emissive), emissiveIntensity: c.emissiveIntensity });
  const accentMat = mat(c.accent, 0.7, 0.3, { emissive: new THREE.Color(c.accent), emissiveIntensity: Math.min(1, c.emissiveIntensity + 0.15) });
  const darkMat = mat(0x0e1113, 0.7, 0.55);
  const polyMat = mat(0x1a1e20, 0.2, 0.85);
  const gloveMat = mat(0x22282a, 0.1, 0.9);
  const cuffMat = new THREE.MeshStandardMaterial({ color: operatorAccent, emissive: new THREE.Color(operatorAccent), emissiveIntensity: 0.3, metalness: 0.3, roughness: 0.6 });

  const L = spec.model.len, B = spec.model.barrel;
  const y = 0, z = 0;

  const add = (geo, m, x, yy, zz, rx = 0, ry = 0, rz = 0) => {
    const mesh = new THREE.Mesh(geo, m);
    mesh.position.set(x, yy, zz);
    mesh.rotation.set(rx, ry, rz);
    mesh.castShadow = false;
    group.add(mesh);
    return mesh;
  };

  // main receiver
  add(new THREE.BoxGeometry(0.075, 0.095, L * 0.62), bodyMat, 0, y, z - L * 0.28);
  // upper rail
  add(new THREE.BoxGeometry(0.05, 0.035, L * 0.6), darkMat, 0, y + 0.062, z - L * 0.28);
  // top rail teeth
  for (let i = 0; i < 7; i++) {
    add(new THREE.BoxGeometry(0.054, 0.012, 0.022), accentMat, 0, y + 0.083, z - L * 0.06 - i * 0.045);
  }
  // handguard
  add(new THREE.BoxGeometry(0.062, 0.07, B * 0.9), bodyMat, 0, y - 0.005, z - L * 0.62 - B * 0.36);
  for (let i = 0; i < 4; i++) {
    add(new THREE.BoxGeometry(0.066, 0.055, 0.026), darkMat, 0, y - 0.005, z - L * 0.66 - i * B * 0.2);
  }
  // barrel
  const barrelGeo = new THREE.CylinderGeometry(0.016, 0.018, B * 0.7, 10);
  add(barrelGeo, darkMat, 0, y + 0.005, z - L * 0.62 - B * 0.76, Math.PI / 2, 0, 0);
  // muzzle brake
  const brake = add(new THREE.CylinderGeometry(0.026, 0.026, 0.075, 8), accentMat, 0, y + 0.005, z - L * 0.62 - B * 1.05, Math.PI / 2, 0, 0);
  for (let i = 0; i < 2; i++) {
    add(new THREE.BoxGeometry(0.058, 0.018, 0.02), darkMat, 0, y + 0.005, z - L * 0.62 - B * 1.0 - i * 0.028);
  }
  // stock
  if (spec.model.stock > 0) {
    add(new THREE.BoxGeometry(0.05, 0.075, spec.model.stock), bodyMat, 0, y - 0.01, z + spec.model.stock * 0.5 + 0.02);
    add(new THREE.BoxGeometry(0.058, 0.11, 0.06), darkMat, 0, y - 0.025, z + spec.model.stock + 0.03);
  }
  // pistol grip
  add(new THREE.BoxGeometry(0.048, 0.13, 0.062), darkMat, 0, y - 0.105, z - 0.015, 0.26, 0, 0);
  // trigger guard
  add(new THREE.BoxGeometry(0.012, 0.012, 0.09), darkMat, 0, y - 0.062, z - 0.09);
  // magazine
  const magH = spec.model.mag;
  const magGeo = new THREE.BoxGeometry(0.05, magH, 0.09);
  add(magGeo, polyMat, 0, y - 0.06 - magH / 2 + 0.04, z - 0.17, 0.16, 0, 0);
  add(new THREE.BoxGeometry(0.054, 0.02, 0.094), accentMat, 0, y - 0.06 - magH + 0.045, z - 0.185, 0.16, 0, 0);

  // foregrip
  add(new THREE.BoxGeometry(0.045, 0.09, 0.055), darkMat, 0, y - 0.07, z - L * 0.62 - B * 0.22, 0.15, 0, 0);

  // optic
  if (spec.model.sight) {
    // rail base
    add(new THREE.BoxGeometry(0.05, 0.03, 0.13), darkMat, 0, y + 0.1, z - L * 0.17);
    // holo frame
    const frame = add(new THREE.TorusGeometry(0.032, 0.006, 6, 16), accentMat, 0, y + 0.155, z - L * 0.17);
    frame.rotation.y = Math.PI / 2;
    // glass
    add(new THREE.CircleGeometry(0.028, 16), new THREE.MeshBasicMaterial({ color: 0x66e8dd, transparent: true, opacity: 0.18, side: THREE.DoubleSide }), 0, y + 0.155, z - L * 0.17, 0, Math.PI / 2, 0);
    // sight post
    add(new THREE.BoxGeometry(0.006, 0.02, 0.006), new THREE.MeshBasicMaterial({ color: 0xff5f52 }), 0, y + 0.15, z - L * 0.17);
  }
  if (weaponId === 'sniper') {
    // scope tube
    add(new THREE.CylinderGeometry(0.038, 0.038, 0.28, 12), darkMat, 0, y + 0.15, z - L * 0.25, Math.PI / 2, 0, 0);
    add(new THREE.CylinderGeometry(0.05, 0.038, 0.07, 12), accentMat, 0, y + 0.15, z - L * 0.25 - 0.17, Math.PI / 2, 0, 0);
    add(new THREE.CylinderGeometry(0.038, 0.05, 0.07, 12), accentMat, 0, y + 0.15, z - L * 0.25 + 0.17, Math.PI / 2, 0, 0);
    // bipod
    add(new THREE.BoxGeometry(0.012, 0.16, 0.012), darkMat, -0.035, y - 0.12, z - L * 0.62 - B * 0.7, 0, 0, 0.35);
    add(new THREE.BoxGeometry(0.012, 0.16, 0.012), darkMat, 0.035, y - 0.12, z - L * 0.62 - B * 0.7, 0, 0, -0.35);
  }
  if (weaponId === 'shotgun') {
    // pump
    add(new THREE.BoxGeometry(0.07, 0.06, 0.22), polyMat, 0, y - 0.03, z - L * 0.62 - B * 0.35);
    // shell tube
    add(new THREE.CylinderGeometry(0.018, 0.018, B * 0.8, 8), darkMat, 0, y - 0.045, z - L * 0.62 - B * 0.5, Math.PI / 2, 0, 0);
  }

  // hands / gloves
  const handR = add(new THREE.BoxGeometry(0.062, 0.1, 0.09), gloveMat, 0.018, y - 0.115, z - 0.01, 0.2, 0, 0);
  add(new THREE.BoxGeometry(0.07, 0.035, 0.075), cuffMat, 0.024, y - 0.165, z + 0.01, 0.2, 0, 0);
  const handL = add(new THREE.BoxGeometry(0.06, 0.09, 0.11), gloveMat, 0.01, y - 0.045, z - L * 0.62 - B * 0.18, 0, 0, 0);
  add(new THREE.BoxGeometry(0.07, 0.035, 0.085), cuffMat, 0.01, y - 0.09, z - L * 0.62 - B * 0.12, 0, 0, 0);

  // side details / glow strips
  add(new THREE.BoxGeometry(0.002, 0.012, L * 0.25), accentMat, 0.0385, y + 0.01, z - L * 0.3);
  add(new THREE.BoxGeometry(0.002, 0.012, L * 0.2), accentMat, -0.0385, y + 0.01, z - L * 0.33);

  const muzzle = new THREE.Vector3(0, y + 0.005, z - L * 0.62 - B * 1.12);

  group.traverse(o => { if (o.isMesh) { o.castShadow = false; o.receiveShadow = false; o.frustumCulled = false; } });
  group.userData = { muzzle, bodyMat, accentMat, skin };
  return group;
}

export function buildBotGun(accent = 0xff5f52) {
  const g = new THREE.Group();
  const body = new THREE.Mesh(new THREE.BoxGeometry(0.07, 0.09, 0.6), mat(0x1a1e21, 0.7, 0.4));
  body.position.z = -0.3; g.add(body);
  const barrel = new THREE.Mesh(new THREE.CylinderGeometry(0.014, 0.014, 0.4, 8), mat(0x101214, 0.8, 0.3));
  barrel.rotation.x = Math.PI / 2; barrel.position.set(0, 0.02, -0.68); g.add(barrel);
  const mag = new THREE.Mesh(new THREE.BoxGeometry(0.045, 0.18, 0.08), mat(0x24282a, 0.4, 0.6));
  mag.position.set(0, -0.12, -0.22); g.add(mag);
  const glow = new THREE.Mesh(new THREE.BoxGeometry(0.075, 0.012, 0.12), new THREE.MeshBasicMaterial({ color: accent }));
  glow.position.set(0, 0.05, -0.2); g.add(glow);
  return g;
}

// ============ VISUAL EFFECTS ============
import * as THREE from 'three';
import { rand } from './util.js';

function glowTexture() {
  const c = document.createElement('canvas');
  c.width = c.height = 128;
  const ctx = c.getContext('2d');
  const g = ctx.createRadialGradient(64, 64, 0, 64, 64, 64);
  g.addColorStop(0, 'rgba(255,255,255,1)');
  g.addColorStop(0.25, 'rgba(255,255,255,.85)');
  g.addColorStop(0.55, 'rgba(255,255,255,.18)');
  g.addColorStop(1, 'rgba(255,255,255,0)');
  ctx.fillStyle = g; ctx.fillRect(0, 0, 128, 128);
  const t = new THREE.CanvasTexture(c);
  t.colorSpace = THREE.SRGBColorSpace;
  return t;
}

function sparkTexture() {
  const c = document.createElement('canvas');
  c.width = c.height = 64;
  const ctx = c.getContext('2d');
  const g = ctx.createRadialGradient(32, 32, 0, 32, 32, 32);
  g.addColorStop(0, 'rgba(255,255,255,1)');
  g.addColorStop(0.3, 'rgba(255,255,255,.9)');
  g.addColorStop(1, 'rgba(255,255,255,0)');
  ctx.fillStyle = g; ctx.fillRect(0, 0, 64, 64);
  const t = new THREE.CanvasTexture(c);
  t.colorSpace = THREE.SRGBColorSpace;
  return t;
}

export class Effects {
  constructor(scene) {
    this.scene = scene;
    this.glowTex = glowTexture();
    this.sparkTex = sparkTexture();
    this.tracers = [];
    this.flashes = [];
    this.particles = [];
    this.shells = [];
    this.explosions = [];
    this.light = new THREE.PointLight(0xffc47a, 0, 14, 2);
    this.light.castShadow = false;
    this.scene.add(this.light);
    this.lightT = 0;
    this.sparkPool = [];
    this.maxParticles = 260;
    for (let i = 0; i < this.maxParticles; i++) {
      const s = new THREE.Sprite(new THREE.SpriteMaterial({ map: this.sparkTex, color: 0xffffff, transparent: true, opacity: 0, blending: THREE.AdditiveBlending, depthWrite: false }));
      s.scale.set(0.12, 0.12, 1);
      s.visible = false;
      this.scene.add(s);
      this.sparkPool.push(s);
    }
  }

  getSpark() {
    return this.sparkPool.find(s => !s.visible) || null;
  }

  tracer(from, to, color = 0xffd9a0, width = 1) {
    const geo = new THREE.BufferGeometry().setFromPoints([from.clone(), to.clone()]);
    const mat = new THREE.LineBasicMaterial({ color, transparent: true, opacity: 0.9, blending: THREE.AdditiveBlending, depthWrite: false });
    const line = new THREE.Line(geo, mat);
    line.frustumCulled = false;
    this.scene.add(line);
    this.tracers.push({ line, life: 0.09, max: 0.09 });
  }

  impact(point, normal, color = 0xffc47a, sound = true) {
    // spark burst
    const count = 7;
    for (let i = 0; i < count; i++) {
      const s = this.getSpark();
      if (!s) break;
      s.visible = true;
      s.position.copy(point).addScaledVector(normal, 0.04);
      s.material.color.set(color);
      s.material.opacity = 0.95;
      s.scale.setScalar(rand(0.04, 0.11));
      const v = new THREE.Vector3(rand(-1, 1), rand(-0.3, 1.2), rand(-1, 1)).multiplyScalar(rand(1.4, 4.2)).addScaledVector(normal, rand(1, 2.5));
      s.userData = { v, life: rand(0.18, 0.4), max: 0.4 };
      this.particles.push(s);
    }
    // flash sprite
    const sprite = new THREE.Sprite(new THREE.SpriteMaterial({ map: this.glowTex, color, transparent: true, opacity: 0.9, blending: THREE.AdditiveBlending, depthWrite: false }));
    sprite.position.copy(point).addScaledVector(normal, 0.06);
    sprite.scale.setScalar(rand(0.25, 0.5));
    this.scene.add(sprite);
    this.flashes.push({ sprite, life: 0.07, max: 0.07, grow: 1.6 });
    // dust puff
    const dust = new THREE.Sprite(new THREE.SpriteMaterial({ map: this.glowTex, color: 0x8a8174, transparent: true, opacity: 0.28, depthWrite: false }));
    dust.position.copy(point).addScaledVector(normal, 0.1);
    dust.scale.setScalar(0.35);
    this.scene.add(dust);
    this.flashes.push({ sprite: dust, life: 0.4, max: 0.4, grow: 2.6, fade: 0.25 });
  }

  muzzleFlash(worldPos, dir, color = 0xffc987) {
    const sprite = new THREE.Sprite(new THREE.SpriteMaterial({ map: this.glowTex, color, transparent: true, opacity: 0.95, blending: THREE.AdditiveBlending, depthWrite: false }));
    sprite.position.copy(worldPos);
    sprite.scale.setScalar(rand(0.25, 0.45));
    this.scene.add(sprite);
    this.flashes.push({ sprite, life: 0.055, max: 0.055, grow: 1.2 });
    this.light.position.copy(worldPos);
    this.light.color.set(color);
    this.light.intensity = 14;
    this.lightT = 0.06;
  }

  hitBurst(point, color = 0x5ce8d4) {
    for (let i = 0; i < 9; i++) {
      const s = this.getSpark();
      if (!s) break;
      s.visible = true;
      s.position.copy(point);
      s.material.color.set(color);
      s.material.opacity = 1;
      s.scale.setScalar(rand(0.05, 0.13));
      const v = new THREE.Vector3(rand(-2, 2), rand(0.2, 2.4), rand(-2, 2));
      s.userData = { v, life: rand(0.2, 0.45), max: 0.45 };
      this.particles.push(s);
    }
  }

  killBurst(point, color = 0xff5f52) {
    this.hitBurst(point, color);
    const ring = new THREE.Mesh(new THREE.RingGeometry(0.2, 0.28, 24), new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 0.9, side: THREE.DoubleSide, blending: THREE.AdditiveBlending, depthWrite: false }));
    ring.position.copy(point);
    ring.lookAt(point.clone().add(new THREE.Vector3(0, 0, 1)));
    this.scene.add(ring);
    this.explosions.push({ mesh: ring, life: 0.35, max: 0.35, type: 'ring' });
  }

  shell(pos, dir) {
    if (this.shells.length > 26) {
      const old = this.shells.shift();
      this.scene.remove(old.mesh);
      old.mesh.geometry.dispose();
      old.mesh.material.dispose();
    }
    const geo = new THREE.CylinderGeometry(0.012, 0.012, 0.045, 6);
    const m = new THREE.Mesh(geo, new THREE.MeshStandardMaterial({ color: 0xc8a75a, metalness: 0.9, roughness: 0.3 }));
    m.position.copy(pos);
    const v = new THREE.Vector3(rand(-1.2, 1.2), rand(0.8, 2), rand(-1.2, 1.2)).addScaledVector(dir, 0.8);
    this.scene.add(m);
    this.shells.push({ mesh: m, v, life: 2.2, spin: new THREE.Vector3(rand(-12, 12), rand(-12, 12), rand(-12, 12)) });
  }

  explosion(pos, color = 0xffb454) {
    const light = new THREE.PointLight(color, 90, 30, 2);
    light.position.copy(pos).add(new THREE.Vector3(0, 1, 0));
    this.scene.add(light);
    this.explosions.push({ light, life: 0.4, max: 0.4, type: 'light', base: 90 });

    const sphere = new THREE.Mesh(new THREE.SphereGeometry(1, 16, 12), new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 0.9, blending: THREE.AdditiveBlending, depthWrite: false }));
    sphere.position.copy(pos).add(new THREE.Vector3(0, 0.7, 0));
    this.scene.add(sphere);
    this.explosions.push({ mesh: sphere, life: 0.28, max: 0.28, type: 'sphere', base: 0.4, target: 4.6 });

    const ring = new THREE.Mesh(new THREE.RingGeometry(0.5, 0.8, 32), new THREE.MeshBasicMaterial({ color: 0xffe0b0, transparent: true, opacity: 0.8, side: THREE.DoubleSide, blending: THREE.AdditiveBlending, depthWrite: false }));
    ring.rotation.x = -Math.PI / 2;
    ring.position.set(pos.x, 0.08, pos.z);
    this.scene.add(ring);
    this.explosions.push({ mesh: ring, life: 0.5, max: 0.5, type: 'ring', base: 1, target: 9 });

    for (let i = 0; i < 26; i++) {
      const s = this.getSpark();
      if (!s) break;
      s.visible = true;
      s.position.copy(pos).add(new THREE.Vector3(rand(-0.4, 0.4), rand(0.3, 1.5), rand(-0.4, 0.4)));
      s.material.color.set(i % 3 ? color : 0xfff2d4);
      s.material.opacity = 1;
      s.scale.setScalar(rand(0.08, 0.24));
      const v = new THREE.Vector3(rand(-6, 6), rand(1, 8), rand(-6, 6));
      s.userData = { v, life: rand(0.3, 0.8), max: 0.8 };
      this.particles.push(s);
    }
    // smoke
    for (let i = 0; i < 10; i++) {
      const sm = new THREE.Sprite(new THREE.SpriteMaterial({ map: this.glowTex, color: 0x2a2a28, transparent: true, opacity: 0.35, depthWrite: false }));
      sm.position.set(pos.x + rand(-1.4, 1.4), rand(0.5, 2), pos.z + rand(-1.4, 1.4));
      sm.scale.setScalar(rand(0.8, 1.8));
      this.scene.add(sm);
      this.explosions.push({ smoke: sm, life: rand(0.8, 1.5), max: 1.5, type: 'smoke', vy: rand(0.4, 1.2) });
    }
  }

  update(dt) {
    // light flash
    if (this.lightT > 0) {
      this.lightT -= dt;
      this.light.intensity = Math.max(0, this.light.intensity - dt * 260);
    } else this.light.intensity = 0;

    for (let i = this.tracers.length - 1; i >= 0; i--) {
      const t = this.tracers[i];
      t.life -= dt;
      t.line.material.opacity = Math.max(0, t.life / t.max) * 0.9;
      if (t.life <= 0) {
        this.scene.remove(t.line);
        t.line.geometry.dispose();
        t.line.material.dispose();
        this.tracers.splice(i, 1);
      }
    }

    for (let i = this.flashes.length - 1; i >= 0; i--) {
      const f = this.flashes[i];
      f.life -= dt;
      const k = 1 - f.life / f.max;
      f.sprite.scale.setScalar(f.sprite.scale.x * (1 + f.grow * dt));
      f.sprite.material.opacity = Math.max(0, (1 - k) * (f.fade || 0.95));
      if (f.life <= 0) {
        this.scene.remove(f.sprite);
        f.sprite.material.dispose();
        this.flashes.splice(i, 1);
      }
    }

    for (let i = this.particles.length - 1; i >= 0; i--) {
      const p = this.particles[i];
      const u = p.userData;
      u.life -= dt;
      if (u.life <= 0) {
        p.visible = false;
        if (p.isSprite && !this.sparkPool.includes(p)) { this.scene.remove(p); p.material.dispose(); }
        this.particles.splice(i, 1);
        continue;
      }
      u.v.y -= 9.8 * dt * 0.6;
      p.position.addScaledVector(u.v, dt);
      p.material.opacity = Math.min(1, u.life / u.max) * 0.95;
    }

    for (let i = this.shells.length - 1; i >= 0; i--) {
      const s = this.shells[i];
      s.life -= dt;
      s.v.y -= 16 * dt;
      s.mesh.position.addScaledVector(s.v, dt);
      if (s.mesh.position.y < 0.03) { s.mesh.position.y = 0.03; s.v.y *= -0.32; s.v.x *= 0.6; s.v.z *= 0.6; }
      s.mesh.rotation.x += s.spin.x * dt; s.mesh.rotation.y += s.spin.y * dt; s.mesh.rotation.z += s.spin.z * dt;
      if (s.life <= 0) {
        this.scene.remove(s.mesh);
        s.mesh.geometry.dispose(); s.mesh.material.dispose();
        this.shells.splice(i, 1);
      }
    }

    for (let i = this.explosions.length - 1; i >= 0; i--) {
      const e = this.explosions[i];
      e.life -= dt;
      const k = 1 - e.life / e.max;
      if (e.type === 'light') e.light.intensity = e.base * (1 - k) * (1 - k);
      if (e.type === 'sphere') { e.mesh.scale.setScalar(e.base + (e.target - e.base) * k); e.mesh.material.opacity = 0.9 * (1 - k); }
      if (e.type === 'ring') { const s = e.base + (e.target - e.base) * k; e.mesh.scale.setScalar(Math.max(1, s)); e.mesh.material.opacity = 0.8 * (1 - k); }
      if (e.type === 'smoke') { e.smoke.position.y += e.vy * dt; e.smoke.material.opacity = 0.35 * (1 - k); e.smoke.scale.multiplyScalar(1 + dt * 0.6); }
      if (e.life <= 0) {
        if (e.light) this.scene.remove(e.light);
        if (e.mesh) { this.scene.remove(e.mesh); e.mesh.geometry.dispose(); e.mesh.material.dispose(); }
        if (e.smoke) { this.scene.remove(e.smoke); e.smoke.material.dispose(); }
        this.explosions.splice(i, 1);
      }
    }
  }

  clear() {
    for (const t of this.tracers) { this.scene.remove(t.line); t.line.geometry.dispose(); t.line.material.dispose(); }
    this.tracers.length = 0;
    for (const f of this.flashes) { this.scene.remove(f.sprite); f.sprite.material.dispose(); }
    this.flashes.length = 0;
    for (const p of this.particles) { p.visible = false; if (!this.sparkPool.includes(p)) this.scene.remove(p); }
    this.particles.length = 0;
    for (const s of this.shells) { this.scene.remove(s.mesh); s.mesh.geometry.dispose(); s.mesh.material.dispose(); }
    this.shells.length = 0;
    for (const e of this.explosions) {
      if (e.light) this.scene.remove(e.light);
      if (e.mesh) { this.scene.remove(e.mesh); e.mesh.geometry.dispose(); e.mesh.material.dispose(); }
      if (e.smoke) { this.scene.remove(e.smoke); e.smoke.material.dispose(); }
    }
    this.explosions.length = 0;
  }
}

// ============ PLAYER CONTROLLER ============
import * as THREE from 'three';
import { WEAPONS, SKINS, OPERATORS } from './config.js';
import { buildWeaponModel } from './weapons.js';
import { clamp, damp, lerp, rand } from './util.js';
import { audio } from './audio.js';

const EYE_STAND = 1.62;
const EYE_CROUCH = 1.03;
const HEIGHT_STAND = 1.78;
const HEIGHT_CROUCH = 1.28;
const RADIUS = 0.34;

export class Player {
  constructor(game) {
    this.game = game;
    this.camera = game.camera;
    this.pos = new THREE.Vector3(0, 0, 38);
    this.vel = new THREE.Vector3();
    this.yaw = 0;
    this.pitch = 0;
    this.lookYaw = 0;
    this.lookPitch = 0;
    this.grounded = true;
    this.crouching = false;
    this.height = HEIGHT_STAND;
    this.eye = EYE_STAND;
    this.stamina = 100;
    this.health = 100;
    this.maxHealth = 100;
    this.alive = true;
    this.deadTime = 0;
    this.sprinting = false;
    this.sliding = false;
    this.slideTime = 0;
    this.slideCooldown = 0;
    this.ads = false;
    this.adsAmount = 0;
    this.bloom = 0;
    this.fireCooldown = 0;
    this.reloading = false;
    this.reloadEnd = 0;
    this.swapEnd = 0;
    this.weaponIndex = 0;
    this.primaryId = 'ar';
    this.camoId = 'camo_standard';
    this.operatorId = 'op_standard';
    this.ammo = {};
    this.grenades = 1;
    this.meleeCooldown = 0;
    this.lastDamage = -99;
    this.lastStep = 0;
    this.bobPhase = 0;
    this.cameraShake = 0;
    this.pitchKick = 0;
    this.yawKick = 0;
    this.gunKick = 0;
    this.viewmodel = null;
    this.kills = 0;
    this.deaths = 0;
    this.headshots = 0;
    this.shotsFired = 0;
    this.shotsHit = 0;
    this.damageDealt = 0;
    this.assists = 0;
    this.currentTarget = null;
    this.hurtT = 0;
    this.lastHitAt = 0;
    this.buildViewmodel();
    this.camera.rotation.order = 'YXZ';
  }

  get team() { return 'blue'; }
  get weapon() { return this.weaponIndex === 0 ? WEAPONS[this.primaryId] : WEAPONS.pistol; }
  get weaponLabel() { return this.weapon.name; }

  buildViewmodel() {
    if (this.viewmodel) {
      this.camera.remove(this.viewmodel);
      this.disposeGroup(this.viewmodel);
    }
    const op = OPERATORS[this.operatorId] || OPERATORS.op_standard;
    this.viewmodel = buildWeaponModel(this.weaponIndex === 0 ? this.primaryId : 'pistol', this.camoId, op.accent);
    this.viewmodel.scale.setScalar(0.92);
    this.basePos = new THREE.Vector3(0.235, -0.195, -0.36);
    this.adsPos = new THREE.Vector3(0.0, -0.105, -0.27);
    this.viewmodel.position.copy(this.basePos);
    this.viewmodel.rotation.set(0, 0, 0);
    this.camera.add(this.viewmodel);
    this.muzzleLocal = this.viewmodel.userData.muzzle;
    this.modelMats = this.viewmodel.userData;
  }

  disposeGroup(g) {
    g.traverse(o => {
      if (o.geometry) o.geometry.dispose();
      if (o.material) {
        if (Array.isArray(o.material)) o.material.forEach(m => m.dispose());
        else o.material.dispose();
      }
    });
  }

  applyLoadout() {
    const r = this.game.profile;
    this.primaryId = r.primary || 'ar';
    this.camoId = r.equipped?.camo || 'camo_standard';
    this.operatorId = r.equipped?.operator || 'op_standard';
    const op = OPERATORS[this.operatorId] || OPERATORS.op_standard;
    this.maxHealth = 100 + (op.armor || 0);
    this.buildViewmodel();
    this.resetAmmo();
  }

  resetAmmo() {
    this.ammo = {
      [this.primaryId]: { mag: WEAPONS[this.primaryId].mag, reserve: WEAPONS[this.primaryId].reserve },
      pistol: { mag: WEAPONS.pistol.mag, reserve: WEAPONS.pistol.reserve }
    };
    this.reloading = false;
    this.fireCooldown = 0;
    this.weaponIndex = 0;
    this.grenades = 1;
  }

  spawn(pos, yaw = 0) {
    this.pos.set(pos.x, 0, pos.z);
    this.vel.set(0, 0, 0);
    this.yaw = yaw; this.lookYaw = yaw;
    this.pitch = 0; this.lookPitch = 0;
    this.health = this.maxHealth;
    this.alive = true;
    this.deadTime = 0;
    this.stamina = 100;
    this.ads = false;
    this.sliding = false;
    this.crouching = false;
    this.height = HEIGHT_STAND;
    this.eye = EYE_STAND;
    this.sprinting = false;
    this.reloading = false;
    this.swapEnd = 0;
    this.bloom = 0;
    if (!this.ammo[this.primaryId]) this.resetAmmo();
    else {
      this.ammo[this.primaryId].mag = WEAPONS[this.primaryId].mag;
      this.ammo.pistol.mag = WEAPONS.pistol.mag;
      this.weaponIndex = 0;
      this.grenades = 1;
    }
    this.buildViewmodel();
    this.updateCamera(0);
    this.game.ui.hideDeath();
  }

  look(dx, dy, sens) {
    if (!this.alive) return;
    const s = sens * (this.ads ? 0.72 : 1);
    this.lookYaw -= dx * s;
    this.lookPitch -= dy * s;
    this.lookPitch = clamp(this.lookPitch, -1.52, 1.52);
  }

  get aimDir() {
    const v = new THREE.Vector3(0, 0, -1);
    v.applyEuler(new THREE.Euler(this.pitch + this.pitchKick, this.yaw + this.yawKick, 0, 'YXZ'));
    return v;
  }

  update(dt) {
    if (!this.alive) {
      this.deadTime += dt;
      this.updateCamera(dt);
      return;
    }
    const inp = this.game.input;
    this.updateWeaponTimers(dt);
    this.updateMovement(dt, inp);
    this.updateCamera(dt);
    this.updateRegen(dt);

    this.fireCooldown = Math.max(0, this.fireCooldown - dt);
    this.meleeCooldown = Math.max(0, this.meleeCooldown - dt);
    this.bloom = damp(this.bloom, 0, 5.5, dt);
    this.gunKick = damp(this.gunKick, 0, 14, dt);
    this.pitchKick = damp(this.pitchKick, 0, 9, dt);
    this.yawKick = damp(this.yawKick, 0, 9, dt);

    if (inp.fire && !this.game.ui.modalOpen) this.tryFire();
    if (inp.reload) this.reload();
    if (inp.grenade) { inp.grenade = false; this.throwGrenade(); }
    if (inp.melee) { inp.melee = false; this.melee(); }
    if (inp.swap) { inp.swap = false; this.swapWeapon(); }
    if (inp.ads) this.ads = true;
    else if (!this.game.touch?.adsToggle) this.ads = false;

    this.adsAmount = damp(this.adsAmount, this.ads ? 1 : 0, 13, dt);
    const w = this.weapon;
    const targetFov = lerp(this.game.baseFov, w.adsFov, this.adsAmount);
    this.camera.fov = damp(this.camera.fov, targetFov, 14, dt);
    this.game.ui.setScope(w.scope && this.adsAmount > 0.75);
    this.game.ui.setAds(this.adsAmount > 0.5);
    if (this.viewmodel) {
      const modeVisible = !(w.scope && this.adsAmount > 0.8);
      this.viewmodel.visible = modeVisible;
      const tp = this.basePos.clone().lerp(this.adsPos, this.adsAmount);
      const bobAmp = this.grounded ? Math.min(1, this.vel.length() / 7) : 0;
      const bobX = Math.sin(this.bobPhase) * 0.008 * bobAmp * (1 - this.adsAmount);
      const bobY = Math.abs(Math.cos(this.bobPhase)) * 0.006 * bobAmp * (1 - this.adsAmount);
      // reload animation
      let reloadRot = 0, reloadDrop = 0;
      if (this.reloading) {
        const d = this.reloadEnd - this.game.matchTime;
        reloadRot = Math.sin(clamp(1 - d / w.reload, 0, 1) * Math.PI) * 0.5;
        reloadDrop = Math.sin(clamp(1 - d / w.reload, 0, 1) * Math.PI) * 0.09;
      }
      const sway = clamp(-this.game.mouseVelX * 0.0009, -0.05, 0.05) * (1 - this.adsAmount);
      this.viewmodel.position.set(
        tp.x + bobX + sway,
        tp.y + bobY - reloadDrop - this.gunKick * 0.02,
        tp.z + this.gunKick * 0.05
      );
      this.viewmodel.rotation.set(
        this.gunKick * 0.09 + reloadRot,
        sway * 1.4,
        -(bobX * 1.5) + (this.sliding ? 0.08 : 0)
      );
    }
    if (this.game.input.crouchToggle) {
      // handled by keydown events
    }
  }

  updateWeaponTimers(dt) {
    if (this.reloading && this.game.matchTime >= this.reloadEnd) this.finishReload();
    if (this.swapEnd && this.game.matchTime >= this.swapEnd) this.swapEnd = 0;
  }

  updateRegen(dt) {
    const since = this.game.matchTime - this.lastDamage;
    if (since > 5.5 && this.health < this.maxHealth) {
      this.health = Math.min(this.maxHealth, this.health + 30 * dt);
    }
    this.hurtT = Math.max(0, this.hurtT - dt);
    this.cameraShake = Math.max(0, this.cameraShake - dt * 3.2);
  }

  updateMovement(dt, inp) {
    const fwd = new THREE.Vector3(-Math.sin(this.yaw), 0, -Math.cos(this.yaw));
    const right = new THREE.Vector3(Math.cos(this.yaw), 0, -Math.sin(this.yaw));
    let moveX = 0, moveZ = 0;
    moveX += (inp.forward ? 1 : 0) - (inp.back ? 1 : 0);
    moveZ += (inp.right ? 1 : 0) - (inp.left ? 1 : 0);
    const hasMove = moveX !== 0 || moveZ !== 0;
    const moveDir = new THREE.Vector3().addScaledVector(fwd, moveX).addScaledVector(right, moveZ);
    if (moveDir.lengthSq() > 0) moveDir.normalize();

    const wantSprint = inp.sprint && moveX > 0.1 && !this.ads && !this.crouching && this.grounded && this.stamina > 2;
    this.sprinting = wantSprint;
    if (wantSprint) this.stamina = Math.max(0, this.stamina - 17 * dt);
    else this.stamina = Math.min(100, this.stamina + (this.crouching ? 22 : 13) * dt);

    // crouch / slide
    if (inp.crouch && !this.crouching && this.grounded) {
      if (this.sprinting || this.vel.length() > 5.5) {
        if (this.slideCooldown <= 0) {
          this.sliding = true;
          this.slideTime = 0.62;
          this.slideCooldown = 1.1;
          this.cameraShake = Math.max(this.cameraShake, 0.5);
          audio.footstep(true);
        }
      }
      this.crouching = true;
    } else if (!inp.crouch && this.crouching && !this.sliding) {
      // ensure headroom
      this.crouching = false;
    }
    if (this.sliding) {
      this.slideTime -= dt;
      if (this.slideTime <= 0) { this.sliding = false; this.slideCooldown = 0.8; }
    }
    this.slideCooldown = Math.max(0, this.slideCooldown - dt);

    let targetHeight = this.crouching ? HEIGHT_CROUCH : HEIGHT_STAND;
    this.height = damp(this.height, targetHeight, 12, dt);
    this.eye = damp(this.eye, this.crouching ? EYE_CROUCH : EYE_STAND, 12, dt);

    const w = this.weapon;
    let speed = 4.65 * (w.speedMult || 1);
    if (this.crouching) speed = 2.35;
    if (this.ads) speed = Math.min(speed, 3.15);
    if (this.sprinting) speed = 7.25;
    if (this.sliding) speed = lerp(4, 9.6, clamp(this.slideTime / 0.62, 0, 1));
    if (this.reloading) speed *= 0.92;

    const targetVel = moveDir.clone().multiplyScalar(hasMove ? speed : 0);
    const accel = this.grounded ? (this.sliding ? 5 : 15) : 4.5;
    this.vel.x = damp(this.vel.x, targetVel.x, accel, dt);
    this.vel.z = damp(this.vel.z, targetVel.z, accel, dt);

    // jump
    if (inp.jump && this.grounded && !this.crouching) {
      this.vel.y = 6.6;
      this.grounded = false;
      inp.jump = false;
      this.stamina = Math.max(0, this.stamina - 4);
    }
    this.vel.y -= 21 * dt;

    this.moveAndCollide(dt);

    // footsteps + bob
    const horizSpeed = Math.hypot(this.vel.x, this.vel.z);
    if (this.grounded && horizSpeed > 1.2) {
      this.bobPhase += dt * (this.sprinting ? 12 : this.crouching ? 6 : 8.5) * clamp(horizSpeed / 5, 0.5, 1.4);
      const stepDist = (this.game.matchTime - this.lastStep);
      if (stepDist > (this.sprinting ? 0.3 : 0.42)) {
        this.lastStep = this.game.matchTime;
        audio.footstep(this.sprinting);
        this.cameraShake = Math.max(this.cameraShake, this.sprinting ? 0.22 : 0.12);
      }
    }
    this.sprinting = this.sprinting && horizSpeed > 4.5;
  }

  moveAndCollide(dt) {
    const colliders = this.game.world.colliders;
    const steps = Math.max(1, Math.ceil((Math.abs(this.vel.x) + Math.abs(this.vel.z) + Math.abs(this.vel.y)) * dt / 0.22));
    const sdt = dt / steps;
    for (let s = 0; s < steps; s++) {
      this.pos.x += this.vel.x * sdt;
      this.pos.z += this.vel.z * sdt;
      this.resolveHorizontal(colliders);
      this.pos.y += this.vel.y * sdt;
      this.resolveVertical(colliders);
    }
    this.pos.x = clamp(this.pos.x, -45.8, 45.8);
    this.pos.z = clamp(this.pos.z, -45.8, 45.8);
  }

  resolveHorizontal(colliders) {
    const r = RADIUS;
    const feet = this.pos.y;
    const head = feet + this.height;
    for (const c of colliders) {
      if (head <= c.min.y + 0.02 || feet >= c.max.y - 0.02) continue;
      // step up onto low obstacles
      if (this.grounded && c.max.y - feet > 0 && c.max.y - feet <= 0.44 && c.max.y - c.min.y < 3) {
        const cx = clamp(this.pos.x, c.min.x, c.max.x);
        const cz = clamp(this.pos.z, c.min.z, c.max.z);
        const dx = this.pos.x - cx, dz = this.pos.z - cz;
        if (dx * dx + dz * dz < r * r) {
          this.pos.y = c.max.y;
          continue;
        }
      }
      const cx = clamp(this.pos.x, c.min.x, c.max.x);
      const cz = clamp(this.pos.z, c.min.z, c.max.z);
      let dx = this.pos.x - cx;
      let dz = this.pos.z - cz;
      const d2 = dx * dx + dz * dz;
      if (d2 >= r * r) continue;
      if (d2 > 1e-8) {
        const d = Math.sqrt(d2);
        const push = (r - d) + 0.001;
        this.pos.x += (dx / d) * push;
        this.pos.z += (dz / d) * push;
      } else {
        // center inside box — push out along nearest face
        const px = Math.min(this.pos.x - c.min.x, c.max.x - this.pos.x);
        const pz = Math.min(this.pos.z - c.min.z, c.max.z - this.pos.z);
        if (px < pz) this.pos.x += (this.pos.x < (c.min.x + c.max.x) / 2 ? -1 : 1) * (px + r);
        else this.pos.z += (this.pos.z < (c.min.z + c.max.z) / 2 ? -1 : 1) * (pz + r);
      }
    }
  }

  resolveVertical(colliders) {
    const r = RADIUS * 0.9;
    const feet = this.pos.y;
    // ceiling
    if (this.vel.y > 0) {
      const head = feet + this.height;
      for (const c of colliders) {
        if (c.min.y < head && c.min.y > feet) {
          const cx = clamp(this.pos.x, c.min.x, c.max.x);
          const cz = clamp(this.pos.z, c.min.z, c.max.z);
          if ((this.pos.x - cx) ** 2 + (this.pos.z - cz) ** 2 < r * r) {
            this.pos.y = c.min.y - this.height - 0.01;
            this.vel.y = 0;
            break;
          }
        }
      }
    }
    let ground = 0;
    let found = false;
    for (const c of colliders) {
      if (c.max.y > this.pos.y + 0.35) continue;
      const cx = clamp(this.pos.x, c.min.x, c.max.x);
      const cz = clamp(this.pos.z, c.min.z, c.max.z);
      if ((this.pos.x - cx) ** 2 + (this.pos.z - cz) ** 2 < r * r) {
        if (c.max.y > ground) { ground = c.max.y; found = true; }
      }
    }
    if (this.pos.y <= ground + 0.001 && this.vel.y <= 0) {
      this.pos.y = ground;
      if (!this.grounded && this.vel.y < -12) this.cameraShake = Math.max(this.cameraShake, 0.5);
      this.vel.y = 0;
      this.grounded = true;
    } else {
      this.grounded = false;
    }
    if (this.pos.y < 0) { this.pos.y = 0; this.vel.y = 0; this.grounded = true; }
    void found;
  }

  updateCamera(dt) {
    const shake = this.cameraShake * 0.012;
    const bob = this.grounded ? Math.sin(this.bobPhase) * 0.018 * Math.min(1, this.vel.length() / 6) : 0;
    const shakeX = (Math.random() - 0.5) * shake;
    const shakeY = (Math.random() - 0.5) * shake;
    this.camera.position.set(
      this.pos.x + shakeX,
      this.pos.y + this.eye + bob + shakeY,
      this.pos.z
    );
    this.yaw = this.lookYaw;
    this.pitch = this.lookPitch;
    this.camera.rotation.set(this.pitch + this.pitchKick, this.yaw + this.yawKick, Math.sin(this.bobPhase * 0.5) * 0.006 + (this.sliding ? 0.04 : 0));
  }

  getSpread() {
    const w = this.weapon;
    let s = lerp(w.spread, w.adsSpread, this.adsAmount);
    const speed = Math.hypot(this.vel.x, this.vel.z);
    s += w.moveSpread * clamp(speed / 7, 0, 1) * (1 - this.adsAmount * 0.75);
    s += this.bloom * 0.012;
    if (this.crouching) s *= 0.8;
    if (!this.grounded) s *= 1.6;
    return s;
  }

  tryFire() {
    if (!this.alive || this.reloading || this.swapEnd) return;
    if (this.fireCooldown > 0) return;
    const w = this.weapon;
    const ammoState = this.ammo[this.weaponIndex === 0 ? this.primaryId : 'pistol'];
    if (!ammoState || ammoState.mag <= 0) {
      this.reload();
      return;
    }
    if (!w.auto && this.wasFiring && this.game.input.fire) {
      // semi-auto: require release
      return;
    }
    this.wasFiring = true;
    ammoState.mag--;
    this.shotsFired++;
    this.fireCooldown = 60 / w.rpm;
    this.bloom = Math.min(1.6, this.bloom + (w.pellets > 1 ? 0.4 : 0.18));
    const baseDir = this.aimDir;
    const origin = this.camera.position.clone();
    const right = new THREE.Vector3().crossVectors(baseDir, new THREE.Vector3(0, 1, 0)).normalize();
    const up = new THREE.Vector3().crossVectors(right, baseDir).normalize();
    const spread = this.getSpread();
    let anyHit = false;
    for (let p = 0; p < w.pellets; p++) {
      const ang = Math.random() * Math.PI * 2;
      const rad = Math.sqrt(Math.random()) * spread;
      const dir = baseDir.clone().addScaledVector(right, Math.cos(ang) * rad).addScaledVector(up, Math.sin(ang) * rad).normalize();
      const hit = this.game.resolveShot(origin, dir, 200, 'blue');
      const end = hit ? hit.point : origin.clone().addScaledVector(dir, 120);
      this.game.effects.tracer(this.muzzleWorld(), end, w.id === 'sniper' ? 0xfff0c0 : 0xffd9a0);
      if (hit) {
        anyHit = true;
        if (hit.bot) {
          const dist = hit.dist;
          const falloff = clamp(1 - (dist / w.range) * w.falloff, w.falloff, 1);
          let dmg = w.damage * falloff;
          const head = hit.part === 'head';
          if (head) dmg *= w.headMult;
          dmg = Math.max(1, Math.round(dmg));
          this.game.damageBot(hit.bot, dmg, head, this, hit.point, w);
          this.shotsHit++;
          this.damageDealt += dmg;
          this.game.ui.hitmarker(head, false);
          this.game.effects.hitBurst(hit.point, head ? 0xffb454 : 0x5ce8d4);
          audio.hit(head);
          if (head) this.headshots++;
        } else {
          this.game.effects.impact(hit.point, hit.normal, 0xffc47a);
        }
      }
      this.game.ui.addBloom(0.15);
    }
    audio.shot(w.id);
    this.game.effects.muzzleFlash(this.muzzleWorld(), baseDir, w.id === 'sniper' ? 0xfff0cf : 0xffc987);
    this.game.effects.shell(this.muzzleWorld().add(new THREE.Vector3(right.x * 0.08, 0, right.z * 0.08)), right);
    this.pitchKick += (w.recoil * 0.012) * (1 - this.adsAmount * 0.3) * rand(0.8, 1.2);
    this.yawKick += rand(-1, 1) * w.recoilYaw * 0.004;
    this.gunKick += 1.2;
    this.cameraShake = Math.max(this.cameraShake, w.id === 'sniper' ? 1.6 : 0.45);
    if (this.game.settings.shake === false) this.cameraShake = 0;
    this.game.ui.updateAmmo();
    if (ammoState.mag <= 0) this.reload();
    void anyHit;
  }

  muzzleWorld() {
    const v = this.muzzleLocal.clone();
    this.viewmodel.updateMatrixWorld(true);
    return this.viewmodel.localToWorld(v);
  }

  reload() {
    if (this.reloading || this.swapEnd) return;
    const key = this.weaponIndex === 0 ? this.primaryId : 'pistol';
    const state = this.ammo[key];
    if (!state || state.mag >= WEAPONS[key === 'pistol' ? 'pistol' : key].mag || state.reserve <= 0) return;
    this.reloading = true;
    this.ads = false;
    this.reloadEnd = this.game.matchTime + this.weapon.reload;
    audio.reload();
    this.game.ui.showReload(true);
  }

  finishReload() {
    const key = this.weaponIndex === 0 ? this.primaryId : 'pistol';
    const w = WEAPONS[key];
    const state = this.ammo[key];
    const need = w.mag - state.mag;
    const take = Math.min(need, state.reserve);
    state.mag += take;
    state.reserve -= take;
    this.reloading = false;
    this.game.ui.showReload(false);
    this.game.ui.updateAmmo();
  }

  swapWeapon() {
    if (this.swapEnd || this.reloading) return;
    this.weaponIndex = this.weaponIndex === 0 ? 1 : 0;
    this.ads = false;
    this.swapEnd = this.game.matchTime + 0.45;
    this.buildViewmodel();
    this.game.ui.updateAmmo();
    this.game.ui.showWeaponName(this.weapon.name);
    audio.ui();
  }

  throwGrenade() {
    if (this.grenades <= 0 || this.swapEnd) return;
    this.grenades--;
    const dir = this.aimDir;
    const origin = this.camera.position.clone().addScaledVector(dir, 0.5);
    this.game.spawnGrenade(origin, dir.clone().multiplyScalar(17).add(new THREE.Vector3(0, 3.5, 0)), this.team, this);
    this.game.ui.updateEquipment();
    audio.ui();
  }

  melee() {
    if (this.meleeCooldown > 0) return;
    this.meleeCooldown = 0.9;
    const origin = this.camera.position.clone();
    const dir = this.aimDir;
    const hit = this.game.resolveShot(origin, dir, 2.6, 'blue');
    if (hit && hit.bot) {
      this.game.damageBot(hit.bot, 90, false, this, hit.point, { name: 'MELEE' });
      this.game.ui.hitmarker(false, true);
      audio.hit(false);
    } else if (hit) {
      this.game.effects.impact(hit.point, hit.normal, 0xffc47a);
    }
    audio.reload();
  }

  takeDamage(amount, fromPos, attacker, weaponName = 'UNKNOWN') {
    if (!this.alive || this.game.matchState !== 'live') return;
    this.health -= amount;
    this.lastDamage = this.game.matchTime;
    this.hurtT = 1;
    this.cameraShake = Math.max(this.cameraShake, 0.9);
    audio.hurt();
    this.game.ui.damageFlash();
    this.game.ui.damageDirection(fromPos, this.pos, this.yaw);
    this.game.ui.updateHealth();
    if (this.health <= 0) {
      this.health = 0;
      this.die(attacker, weaponName);
    }
  }

  die(attacker, weaponName) {
    this.alive = false;
    this.deaths++;
    this.deadTime = 0;
    this.ads = false;
    this.sliding = false;
    this.reloading = false;
    this.game.onPlayerDeath(attacker, weaponName);
  }

  heal(amount) {
    this.health = Math.min(this.maxHealth, this.health + amount);
    this.game.ui.updateHealth();
  }
}

// ============ BOT SOLDIERS & AI ============
import * as THREE from 'three';
import { BOT_NAMES, WEAPONS, DIFFICULTY, CONTROL_POINTS, SPAWNS, MODES } from './config.js';
import { buildBotGun } from './weapons.js';
import { clamp, damp, lerp, rand, randInt, pick, rayAABB, raySphere, makeTextSprite } from './util.js';
import { audio } from './audio.js';

const WAYPOINTS = [
  [-35, 22], [35, 22], [-35, -20], [35, -20], [-22, 0], [22, 0],
  [0, -14], [0, 8], [-10, 30], [10, 30], [-29, 5], [29, 5],
  [-6, -28], [6, -28], [-38, -8], [38, -8], [-18, 30], [18, 30],
  [-12, -20], [12, -20], [-20, 12], [20, 12], [0, 18], [0, -30]
];

function soldierMaterials(accent) {
  return {
    suit: new THREE.MeshStandardMaterial({ color: 0x1c2226, roughness: 0.85, metalness: 0.15 }),
    plate: new THREE.MeshStandardMaterial({ color: 0x2a3236, roughness: 0.6, metalness: 0.4 }),
    dark: new THREE.MeshStandardMaterial({ color: 0x0d1012, roughness: 0.8, metalness: 0.2 }),
    accent: new THREE.MeshStandardMaterial({ color: accent, emissive: new THREE.Color(accent), emissiveIntensity: 0.7, roughness: 0.4, metalness: 0.3 }),
    visor: new THREE.MeshBasicMaterial({ color: accent }),
    glove: new THREE.MeshStandardMaterial({ color: 0x151a1c, roughness: 0.9 })
  };
}

export function createSoldier(accent, isAlly = false) {
  const mats = soldierMaterials(accent);
  const group = new THREE.Group();
  const body = new THREE.Group();
  group.add(body);

  const torso = new THREE.Mesh(new THREE.CapsuleGeometry(0.21, 0.38, 4, 8), mats.suit);
  torso.position.y = 1.15; torso.scale.z = 1.25; body.add(torso);
  // chest rig
  const chest = new THREE.Mesh(new THREE.BoxGeometry(0.42, 0.35, 0.26), mats.plate);
  chest.position.set(0, 1.18, 0.02); body.add(chest);
  // shoulder pads
  for (const s of [-1, 1]) {
    const pad = new THREE.Mesh(new THREE.SphereGeometry(0.12, 8, 6), mats.plate);
    pad.position.set(s * 0.25, 1.37, 0); pad.scale.set(1, 0.8, 1.1); body.add(pad);
  }
  // accent chest light
  const light = new THREE.Mesh(new THREE.BoxGeometry(0.15, 0.025, 0.02), mats.accent);
  light.position.set(0, 1.22, 0.155); body.add(light);
  const backLight = new THREE.Mesh(new THREE.BoxGeometry(0.2, 0.05, 0.02), mats.accent);
  backLight.position.set(0, 1.2, -0.15); body.add(backLight);

  // head
  const headGroup = new THREE.Group();
  headGroup.position.y = 1.56;
  const head = new THREE.Mesh(new THREE.SphereGeometry(0.135, 10, 8), mats.dark);
  head.scale.set(0.92, 1, 0.95); headGroup.add(head);
  const helmet = new THREE.Mesh(new THREE.SphereGeometry(0.152, 10, 8, 0, Math.PI * 2, 0, Math.PI * 0.6), mats.plate);
  helmet.position.y = 0.025; headGroup.add(helmet);
  const visor = new THREE.Mesh(new THREE.BoxGeometry(0.19, 0.045, 0.05), mats.visor);
  visor.position.set(0, 0.02, 0.115); headGroup.add(visor);
  // antenna
  const ant = new THREE.Mesh(new THREE.CylinderGeometry(0.006, 0.006, 0.24, 4), mats.dark);
  ant.position.set(0.09, 0.15, -0.04); headGroup.add(ant);
  body.add(headGroup);

  // arms
  const armL = new THREE.Group(); armL.position.set(-0.25, 1.35, 0);
  const upperL = new THREE.Mesh(new THREE.CapsuleGeometry(0.065, 0.24, 4, 6), mats.suit);
  upperL.position.y = -0.16; armL.add(upperL);
  const gloveL = new THREE.Mesh(new THREE.BoxGeometry(0.09, 0.1, 0.11), mats.glove);
  gloveL.position.set(0.02, -0.36, 0.14); armL.add(gloveL);
  armL.rotation.x = -0.9; body.add(armL);

  const armR = new THREE.Group(); armR.position.set(0.25, 1.35, 0);
  const upperR = new THREE.Mesh(new THREE.CapsuleGeometry(0.065, 0.24, 4, 6), mats.suit);
  upperR.position.y = -0.16; armR.add(upperR);
  const gloveR = new THREE.Mesh(new THREE.BoxGeometry(0.09, 0.1, 0.11), mats.glove);
  gloveR.position.set(-0.02, -0.36, 0.1); armR.add(gloveR);
  armR.rotation.x = -0.85; body.add(armR);

  // gun in hands
  const gun = buildBotGun(accent);
  gun.position.set(0.05, 1.22, 0.18);
  gun.rotation.x = 0.02;
  body.add(gun);

  // legs
  const legL = new THREE.Group(); legL.position.set(-0.12, 0.86, 0);
  const legLm = new THREE.Mesh(new THREE.CapsuleGeometry(0.078, 0.5, 4, 6), mats.suit);
  legLm.position.y = -0.3; legL.add(legLm);
  const bootL = new THREE.Mesh(new THREE.BoxGeometry(0.13, 0.11, 0.25), mats.dark);
  bootL.position.set(0, -0.62, 0.05); legL.add(bootL);
  body.add(legL);

  const legR = new THREE.Group(); legR.position.set(0.12, 0.86, 0);
  const legRm = new THREE.Mesh(new THREE.CapsuleGeometry(0.078, 0.5, 4, 6), mats.suit);
  legRm.position.y = -0.3; legR.add(legRm);
  const bootR = new THREE.Mesh(new THREE.BoxGeometry(0.13, 0.11, 0.25), mats.dark);
  bootR.position.set(0, -0.62, 0.05); legR.add(bootR);
  body.add(legR);

  // ally marker
  let marker = null;
  if (isAlly) {
    marker = makeTextSprite('▲', '#5ce8d4', 0.5);
    marker.position.y = 2.0;
    group.add(marker);
  }

  group.traverse(o => { if (o.isMesh) { o.castShadow = true; o.receiveShadow = true; } });
  group.userData = { body, headGroup, legL, legR, armL, armR, gun, mats, marker, head, torso };
  return group;
}

export class Bots {
  constructor(game) {
    this.game = game;
    this.scene = game.scene;
    this.list = [];
    this.nextId = 0;
  }

  setup(mode, difficulty) {
    this.clear();
    const diff = DIFFICULTY[difficulty] || DIFFICULTY.regular;
    const names = [...BOT_NAMES].sort(() => Math.random() - 0.5);
    let count, teams;
    if (mode.ffa) {
      count = mode.teamSize - 1;
      teams = Array.from({ length: count }, (_, i) => ({ team: i % 2 === 0 ? 'red' : 'ffa', accent: [0xff5f52, 0xffb454, 0xb18cff, 0x7dffb0][i % 4] }));
    } else {
      count = (mode.teamSize - 1) + mode.teamSize;
      teams = [];
      for (let i = 0; i < mode.teamSize - 1; i++) teams.push({ team: 'blue', accent: 0x5ce8d4 });
      for (let i = 0; i < mode.teamSize; i++) teams.push({ team: 'red', accent: 0xff5f52 });
    }
    for (let i = 0; i < count; i++) {
      const t = teams[i];
      const bot = this.createBot(names[i % names.length], t.team, t.accent, diff, mode);
      this.list.push(bot);
    }
    // initial placement
    for (const bot of this.list) this.placeAtSpawn(bot);
  }

  createBot(name, team, accent, diff, mode) {
    const ally = !mode.ffa && team === 'blue';
    const mesh = createSoldier(accent, ally);
    this.scene.add(mesh);
    const bot = {
      id: ++this.nextId, name, team, accent, mesh, diff, mode,
      pos: new THREE.Vector3(), vel: new THREE.Vector3(), yaw: 0, aimYaw: 0,
      health: diff.hp, maxHealth: diff.hp, alive: true, respawnAt: 0, deathT: 0,
      target: null, targetSeenAt: 0, reactionAt: 0, state: 'patrol',
      fireTimer: 0, burstLeft: 0, burstCooldown: 0, reloadTimer: 0, ammo: WEAPONS.ar.mag,
      thinkTimer: rand(0, 0.2), strafeDir: Math.random() > 0.5 ? 1 : -1, strafeTimer: 0,
      waypoint: null, kills: 0, deaths: 0, animPhase: rand(0, 10),
      lastSeen: new THREE.Vector3(), lastSeenTime: -99, damageTakenAt: -99,
      accuracy: diff.acc, deadMeshRot: 0
    };
    mesh.userData.bot = bot;
    return bot;
  }

  clear() {
    for (const b of this.list) {
      this.scene.remove(b.mesh);
      b.mesh.traverse(o => {
        if (o.geometry) o.geometry.dispose();
        if (o.material && !o.isSprite) {
          if (Array.isArray(o.material)) o.material.forEach(m => m.dispose());
          else o.material.dispose();
        }
        if (o.isSprite) { o.material.map?.dispose(); o.material.dispose(); }
      });
    }
    this.list = [];
  }

  placeAtSpawn(bot) {
    const mode = this.game.mode;
    let pool;
    if (mode.ffa) pool = SPAWNS.ffa;
    else pool = bot.team === 'blue' ? SPAWNS.blue : SPAWNS.red;
    let best = pool[0], bestScore = -1;
    for (const p of pool) {
      let minDist = 999;
      for (const other of this.list) {
        if (other === bot || !other.alive) continue;
        if (!mode.ffa && other.team === bot.team) continue;
        if (!mode.ffa && other.team !== bot.team) {
          const d = Math.hypot(other.pos.x - p.x, other.pos.z - p.z);
          minDist = Math.min(minDist, d);
        }
      }
      if (this.game.player && this.game.player.alive) {
        const d = Math.hypot(this.game.player.pos.x - p.x, this.game.player.pos.z - p.z);
        if (mode.ffa || bot.team !== 'blue') minDist = Math.min(minDist, d);
      }
      const score = minDist + rand(0, 8);
      if (score > bestScore) { bestScore = score; best = p; }
    }
    const sp = best;
    bot.pos.set(sp.x + rand(-1.4, 1.4), 0, sp.z + rand(-1.4, 1.4));
    bot.yaw = bot.team === 'blue' ? 0 : Math.PI;
    bot.aimYaw = bot.yaw;
    bot.health = bot.maxHealth;
    bot.alive = true;
    bot.respawnAt = 0;
    bot.deathT = 0;
    bot.ammo = WEAPONS.ar.mag;
    bot.reloadTimer = 0;
    bot.target = null;
    bot.mesh.visible = true;
    bot.mesh.rotation.set(0, bot.yaw, 0);
    bot.mesh.userData.body.rotation.set(0, 0, 0);
    bot.mesh.userData.body.position.y = 0;
    bot.mesh.position.copy(bot.pos);
    if (bot.mesh.userData.marker) bot.mesh.userData.marker.visible = true;
  }

  respawn(bot) {
    this.placeAtSpawn(bot);
    this.game.effects.hitBurst(bot.pos.clone().add(new THREE.Vector3(0, 1, 0)), bot.team === 'blue' ? 0x5ce8d4 : 0xff5f52);
    audio.spawn();
  }

  raycast(origin, dir, maxDist, shooterTeam) {
    let best = null;
    for (const b of this.list) {
      if (!b.alive) continue;
      if (!this.game.mode.ffa && b.team === shooterTeam) continue;
      // head
      const headC = new THREE.Vector3(b.pos.x, b.pos.y + 1.58, b.pos.z);
      const th = raySphere(origin, dir, headC, 0.23);
      if (th !== null && th < maxDist && (!best || th < best.dist)) {
        best = { bot: b, dist: th, part: 'head', point: origin.clone().addScaledVector(dir, th) };
      }
      // torso
      const torso = makeBotBox(b, 0.33, 1.62, 0.32, 0.72, 0.44);
      const tt = rayAABB(origin, dir, torso, best ? best.dist : maxDist);
      if (tt !== null && tt > 0 && tt < (best ? best.dist : maxDist)) {
        best = { bot: b, dist: tt, part: 'body', point: origin.clone().addScaledVector(dir, tt) };
      }
      // legs
      const legs = makeBotBox(b, 0.3, 0.82, 0.3, 0.82, 0.4);
      const tl = rayAABB(origin, dir, legs, best ? best.dist : maxDist);
      if (tl !== null && tl > 0 && tl < (best ? best.dist : maxDist)) {
        best = { bot: b, dist: tl, part: 'legs', point: origin.clone().addScaledVector(dir, tl) };
      }
    }
    return best;
  }

  nearestEnemy(bot) {
    let best = null, bestD = Infinity;
    const eye = new THREE.Vector3(bot.pos.x, bot.pos.y + 1.55, bot.pos.z);
    const consider = (x, z, y, ref) => {
      const d = Math.hypot(x - bot.pos.x, z - bot.pos.z);
      if (d >= bestD || d > 62) return;
      const target = new THREE.Vector3(x, y, z);
      if (!this.game.world.lineOfSight(eye, target)) return;
      bestD = d; best = ref;
    };
    for (const b of this.list) {
      if (b === bot || !b.alive) continue;
      if (!this.game.mode.ffa && b.team === bot.team) continue;
      // FOV check for acquisition
      const ang = Math.atan2(b.pos.x - bot.pos.x, b.pos.z - bot.pos.z);
      const diffA = Math.abs(Math.atan2(Math.sin(ang - bot.yaw), Math.cos(ang - bot.yaw)));
      if (diffA > 1.9 && bot.target !== b) continue;
      consider(b.pos.x, b.pos.z, 1.1, b);
    }
    const p = this.game.player;
    if (p && p.alive && (this.game.mode.ffa || bot.team !== 'blue')) {
      const ang = Math.atan2(p.pos.x - bot.pos.x, p.pos.z - bot.pos.z);
      const diffA = Math.abs(Math.atan2(Math.sin(ang - bot.yaw), Math.cos(ang - bot.yaw)));
      if (diffA < 1.9 || bot.target === p) {
        const d = Math.hypot(p.pos.x - bot.pos.x, p.pos.z - bot.pos.z);
        if (d < bestD) consider(p.pos.x, p.pos.z, 1.25, p);
      }
    }
    return best;
  }

  update(dt) {
    const g = this.game;
    for (const bot of this.list) {
      if (!bot.alive) {
        this.updateDeath(bot, dt);
        if (bot.respawnAt && g.matchTime >= bot.respawnAt && g.matchState === 'live') this.respawn(bot);
        continue;
      }
      if (g.matchState !== 'live') {
        this.updateAnimation(bot, dt, 0);
        continue;
      }
      bot.thinkTimer -= dt;
      bot.reactionAt -= dt;
      bot.fireTimer -= dt;
      bot.burstCooldown -= dt;
      bot.strafeTimer -= dt;
      if (bot.reloadTimer > 0) {
        bot.reloadTimer -= dt;
        if (bot.reloadTimer <= 0) bot.ammo = WEAPONS.ar.mag;
      }
      if (bot.thinkTimer <= 0) {
        bot.thinkTimer = rand(0.12, 0.24);
        const enemy = this.nearestEnemy(bot);
        if (enemy && enemy !== bot.target) {
          bot.target = enemy;
          bot.targetSeenAt = g.matchTime;
          bot.reactionAt = bot.diff.reaction * rand(0.7, 1.3);
        } else if (!enemy) {
          bot.target = null;
        }
        if (enemy) {
          bot.lastSeen.copy(enemy.pos || enemy.object?.pos || bot.pos);
          if (enemy.pos) bot.lastSeen.copy(enemy.pos);
          bot.lastSeenTime = g.matchTime;
        }
        if (bot.strafeTimer <= 0) {
          bot.strafeTimer = rand(0.9, 2.2);
          bot.strafeDir *= -1;
        }
      }

      this.updateMovement(bot, dt);
      this.updateCombat(bot, dt);
      this.updateAnimation(bot, dt, Math.hypot(bot.vel.x, bot.vel.z));
    }
  }

  updateDeath(bot, dt) {
    bot.deathT += dt;
    const body = bot.mesh.userData.body;
    if (bot.mesh.visible) {
      bot.deadMeshRot = damp(bot.deadMeshRot, Math.PI / 2, 6, dt);
      body.rotation.z = bot.deadMeshRot * (bot.deathDir || 1);
      body.position.y = Math.max(-0.9, body.position.y - dt * 0.4);
      if (bot.deathT > 2.4) bot.mesh.visible = false;
    }
    void body;
  }

  updateMovement(bot, dt) {
    const g = this.game;
    let desired = new THREE.Vector3();
    const eyePos = new THREE.Vector3(bot.pos.x, 1.55, bot.pos.z);
    const target = bot.target;

    if (target) {
      const tpos = target.pos;
      const dist = Math.hypot(tpos.x - bot.pos.x, tpos.z - bot.pos.z);
      const dirTo = new THREE.Vector3(tpos.x - bot.pos.x, 0, tpos.z - bot.pos.z).normalize();
      if (dist > 24) desired.add(dirTo.multiplyScalar(1));
      else if (dist < 8) desired.add(dirTo.multiplyScalar(-1));
      const strafe = new THREE.Vector3(-dirTo.z, 0, dirTo.x).multiplyScalar(bot.strafeDir * 0.7);
      desired.add(strafe);
      // occasional cover crouch walk toward cover is skipped; maintain spacing from allies
    } else {
      // objective / waypoint
      let goal = null;
      if (g.mode.id === 'dom') {
        const points = CONTROL_POINTS.filter(p => g.points[p.id].owner !== bot.team);
        goal = points.length ? pick(points) : pick(CONTROL_POINTS);
      } else if (g.mode.ffa && g.zoneRadius < 46) {
        const ang = Math.random() * Math.PI * 2;
        goal = { x: g.zoneCenter.x + Math.cos(ang) * g.zoneRadius * 0.5, z: g.zoneCenter.z + Math.sin(ang) * g.zoneRadius * 0.5 };
      } else if (bot.lastSeenTime > g.matchTime - 8) {
        goal = { x: bot.lastSeen.x, z: bot.lastSeen.z };
      } else {
        if (!bot.waypoint || Math.hypot(bot.waypoint[0] - bot.pos.x, bot.waypoint[1] - bot.pos.z) < 3) {
          bot.waypoint = pick(WAYPOINTS);
        }
        goal = { x: bot.waypoint[0], z: bot.waypoint[1] };
      }
      desired.set(goal.x - bot.pos.x, 0, goal.z - bot.pos.z);
      if (desired.lengthSq() < 0.01) desired.set(rand(-1, 1), 0, rand(-1, 1));
      desired.normalize();
    }

    // obstacle avoidance
    if (g.world.blocked(bot.pos.x, bot.pos.z, desired.x, desired.z, 2.0)) {
      let found = false;
      for (const ang of [0.6, -0.6, 1.2, -1.2, 2.0, -2.0]) {
        const c = Math.cos(ang), s = Math.sin(ang);
        const nx = desired.x * c - desired.z * s;
        const nz = desired.x * s + desired.z * c;
        if (!g.world.blocked(bot.pos.x, bot.pos.z, nx, nz, 2.0)) {
          desired.set(nx, 0, nz); found = true; break;
        }
      }
      if (!found) desired.multiplyScalar(-1);
    }

    // separation
    for (const other of this.list) {
      if (other === bot || !other.alive) continue;
      const dx = bot.pos.x - other.pos.x, dz = bot.pos.z - other.pos.z;
      const d2 = dx * dx + dz * dz;
      if (d2 < 2.2 && d2 > 0.001) {
        const d = Math.sqrt(d2);
        desired.x += (dx / d) * 0.6;
        desired.z += (dz / d) * 0.6;
      }
    }
    if (desired.lengthSq() > 0) desired.normalize();

    const speed = target ? (Math.hypot(target.pos.x - bot.pos.x, target.pos.z - bot.pos.z) < 14 ? 2.6 : 3.6) : 3.35;
    bot.vel.x = damp(bot.vel.x, desired.x * speed, 7, dt);
    bot.vel.z = damp(bot.vel.z, desired.z * speed, 7, dt);
    bot.pos.x += bot.vel.x * dt;
    bot.pos.z += bot.vel.z * dt;

    // collide with world (simple circle)
    const r = 0.38;
    for (const c of g.world.colliders) {
      if (c.max.y < 0.35 || c.min.y > 1.7) continue;
      const cx = clamp(bot.pos.x, c.min.x, c.max.x);
      const cz = clamp(bot.pos.z, c.min.z, c.max.z);
      const dx = bot.pos.x - cx, dz = bot.pos.z - cz;
      const d2 = dx * dx + dz * dz;
      if (d2 < r * r && d2 > 1e-8) {
        const d = Math.sqrt(d2);
        bot.pos.x += (dx / d) * (r - d);
        bot.pos.z += (dz / d) * (r - d);
      } else if (d2 <= 1e-8) {
        bot.pos.x += 0.1;
      }
    }
    bot.pos.x = clamp(bot.pos.x, -45, 45);
    bot.pos.z = clamp(bot.pos.z, -45, 45);
    bot.pos.y = 0;
    bot.mesh.position.copy(bot.pos);

    // facing
    let faceYaw = bot.yaw;
    if (target) faceYaw = Math.atan2(-(target.pos.x - bot.pos.x), -(target.pos.z - bot.pos.z));
    else if (Math.hypot(bot.vel.x, bot.vel.z) > 0.3) faceYaw = Math.atan2(-bot.vel.x, -bot.vel.z);
    let dy = Math.atan2(Math.sin(faceYaw - bot.yaw), Math.cos(faceYaw - bot.yaw));
    bot.yaw += dy * Math.min(1, dt * (target ? 9 : 5));
    bot.aimYaw = bot.yaw;
    bot.mesh.rotation.y = bot.yaw;
    void eyePos;
  }

  updateCombat(bot, dt) {
    const g = this.game;
    const target = bot.target;
    if (!target || !target.alive) return;
    if (bot.reloadTimer > 0 || bot.ammo <= 0) {
      if (bot.ammo <= 0 && bot.reloadTimer <= 0) bot.reloadTimer = 1.6;
      return;
    }
    if (bot.reactionAt > 0) return;
    if (bot.fireTimer > 0) return;

    const tx = target.pos.x, tz = target.pos.z;
    const ty = 1.15 + (target === g.player && !g.player.crouching ? 0 : 0);
    const muzzle = new THREE.Vector3(bot.pos.x, 1.22, bot.pos.z);
    const aimPoint = new THREE.Vector3(tx, ty, tz);
    if (target === g.player) aimPoint.y = g.player.pos.y + g.player.eye * 0.62;
    const dist = muzzle.distanceTo(aimPoint);
    if (dist > 62) return;
    if (!g.world.lineOfSight(new THREE.Vector3(bot.pos.x, 1.55, bot.pos.z), aimPoint)) return;
    if (bot.ammo <= 0) return;

    // aim
    const baseDir = new THREE.Vector3().subVectors(aimPoint, muzzle).normalize();
    const right = new THREE.Vector3().crossVectors(baseDir, new THREE.Vector3(0, 1, 0)).normalize();
    const up = new THREE.Vector3().crossVectors(right, baseDir).normalize();
    const spread = 0.006 + (1 - bot.accuracy) * 0.055 + dist * 0.00035;
    const ang = Math.random() * Math.PI * 2;
    const rad = Math.sqrt(Math.random()) * spread;
    const dir = baseDir.clone().addScaledVector(right, Math.cos(ang) * rad).addScaledVector(up, Math.sin(ang) * rad).normalize();

    bot.ammo--;
    bot.fireTimer = 60 / WEAPONS.ar.rpm;
    bot.burstLeft--;
    const hit = g.resolveShot(muzzle, dir, 90, bot.team);
    const end = hit ? hit.point : muzzle.clone().addScaledVector(dir, 70);
    g.effects.tracer(muzzle, end, bot.team === 'blue' ? 0x9fe8de : 0xffa090, 1);
    g.effects.muzzleFlash(muzzle, dir, bot.team === 'blue' ? 0xaef5ea : 0xffb08a);
    audio.shot('ar');
    if (hit) {
      if (hit.bot) {
        g.damageBot(hit.bot, Math.round(rand(8, 13) * bot.diff.damage), false, bot, hit.point, { name: 'VK-7 HAVOC' });
      } else if (hit.player) {
        g.player.takeDamage(Math.round(rand(8, 13) * bot.diff.damage), bot.pos, bot.name, 'VK-7 HAVOC');
        g.effects.hitBurst(hit.point, 0xff5f52);
      } else {
        g.effects.impact(hit.point, hit.normal, 0xffc47a);
      }
    }
    if (bot.burstLeft <= 0) {
      bot.burstLeft = randInt(bot.diff.burst[0], bot.diff.burst[1]);
      bot.fireTimer = bot.burstCooldown = rand(0.7, 1.5) / (bot.diff.acc + 0.5);
    }
    if (bot.ammo <= 0) bot.reloadTimer = 1.5;
  }

  updateAnimation(bot, dt, speed) {
    const u = bot.mesh.userData;
    bot.animPhase += dt * (speed > 0.3 ? 9 : 1.6);
    const swing = Math.min(1, speed / 3.2) * 0.55;
    u.legL.rotation.x = Math.sin(bot.animPhase) * swing;
    u.legR.rotation.x = -Math.sin(bot.animPhase) * swing;
    u.body.position.y = Math.abs(Math.sin(bot.animPhase)) * 0.02 * (speed > 0.3 ? 1 : 0);
    u.body.rotation.x = speed > 0.3 ? 0.03 : 0;
    if (u.marker) {
      u.marker.visible = bot.alive && this.game.player?.alive;
      if (u.marker.visible) {
        const dist = this.game.player.pos.distanceTo(bot.pos);
        u.marker.visible = dist < 55;
        u.marker.material.opacity = clamp(1.2 - dist / 60, 0.15, 0.9);
      }
    }
  }

  reset() {
    for (const b of this.list) {
      this.placeAtSpawn(b);
      b.kills = 0; b.deaths = 0;
      b.mesh.visible = true;
    }
  }
}

function makeBotBox(bot, halfW, height, halfD, y0, y1) {
  return {
    min: new THREE.Vector3(bot.pos.x - halfW, bot.pos.y + y0 - height / 2, bot.pos.z - halfD),
    max: new THREE.Vector3(bot.pos.x + halfW, bot.pos.y + y0 + height / 2, bot.pos.z + halfD)
  };
}

