// ============ ECONOMY: PROFILE, STORE, REWARDS, SETTLEMENT ============
import { SKINS, OPERATORS, STORE_ITEMS, BATTLE_PASS, BP_XP_PER_TIER, SRN_USD, REWARDS } from './config.js';
import { randomHex } from './util.js';

const KEY = 'sentinel_profile_v2';

function defaultProfile() {
  return {
    version: 2,
    callsign: 'RECRUIT-01',
    createdAt: Date.now(),
    credits: 1200,
    srn: 250,
    pending: 0,
    seasonEarned: 0,
    xp: 0,
    level: 1,
    matches: 0,
    wins: 0,
    kills: 0,
    deaths: 0,
    primary: 'ar',
    ownedCamos: ['camo_standard'],
    ownedOperators: ['op_standard'],
    equipped: { camo: 'camo_standard', operator: 'op_standard' },
    pass: { premium: false, xp: 0, tier: 1, claimed: [] },
    subscription: { active: false, since: 0, plan: '' },
    wallet: '0x' + randomHex(40),
    txs: [],
    settings: { sens: 50, fov: 80, quality: 'medium', volume: 65, difficulty: 'regular', touch: 'auto', bloom: true, shake: true, invert: false }
  };
}

class Economy {
  constructor() {
    this.profile = this.load();
    if (!this.profile.wallet) this.profile.wallet = '0x' + randomHex(40);
    this.listeners = [];
  }

  load() {
    try {
      const raw = localStorage.getItem(KEY);
      if (!raw) return defaultProfile();
      const p = JSON.parse(raw);
      const base = defaultProfile();
      return { ...base, ...p, settings: { ...base.settings, ...(p.settings || {}) }, pass: { ...base.pass, ...(p.pass || {}) }, equipped: { ...base.equipped, ...(p.equipped || {}) } };
    } catch { return defaultProfile(); }
  }

  save() {
    try { localStorage.setItem(KEY, JSON.stringify(this.profile)); } catch {}
    this.emit();
  }

  onChange(fn) { this.listeners.push(fn); }
  emit() { for (const fn of this.listeners) fn(this.profile); }

  reset() {
    localStorage.removeItem(KEY);
    this.profile = defaultProfile();
    this.save();
  }

  get passTier() { return this.profile.pass.tier; }
  get level() { return 1 + Math.floor(this.profile.xp / 1200); }
  get storeDiscount() { return this.profile.subscription.active ? 0.1 : 1; }

  camoPrice(item) { return Math.round(item.price * this.storeDiscount); }

  priceFor(item) {
    return Math.round(item.price * this.storeDiscount);
  }

  canAfford(credits) { return this.profile.credits >= credits; }

  addCredits(n, label = 'Credit top-up') {
    this.profile.credits += n;
    this.profile.txs.unshift({ type: 'purchase', label, amount: n, symbol: 'CR', hash: 'cs_' + randomHex(24), date: Date.now(), status: 'paid' });
    this.trimTx();
    this.save();
  }

  addPending(n) {
    this.profile.pending = +(this.profile.pending + n).toFixed(2);
    this.profile.seasonEarned = +(this.profile.seasonEarned + n).toFixed(2);
    this.save();
  }

  async settle() {
    if (this.profile.pending <= 0) return { ok: false, reason: 'NO_PENDING' };
    const amount = +this.profile.pending.toFixed(2);
    await new Promise(r => setTimeout(r, 1500));
    const tx = {
      type: 'settle', label: 'Match rewards settled', amount,
      symbol: 'SRN', hash: '0x' + randomHex(64), date: Date.now(), status: 'confirmed',
      gas: +(0.0018 + Math.random() * 0.0012).toFixed(4)
    };
    this.profile.pending = 0;
    this.profile.srn = +(this.profile.srn + amount).toFixed(2);
    this.profile.txs.unshift(tx);
    this.trimTx();
    this.save();
    return { ok: true, tx };
  }

  trimTx() { if (this.profile.txs.length > 30) this.profile.txs.length = 30; }

  ownCamo(id) { return this.profile.ownedCamos.includes(id); }
  ownOperator(id) { return this.profile.ownedOperators.includes(id); }

  equipCamo(id) {
    if (!this.ownCamo(id)) return false;
    this.profile.equipped.camo = id;
    this.save();
    return true;
  }

  equipOperator(id) {
    if (!this.ownOperator(id)) return false;
    this.profile.equipped.operator = id;
    this.save();
    return true;
  }

  setPrimary(id) {
    this.profile.primary = id;
    this.save();
  }

  grant(grants = {}) {
    const result = { credits: 0, camos: [], operators: [], tiers: 0 };
    if (grants.credits) {
      this.profile.credits += grants.credits;
      result.credits = grants.credits;
    }
    for (const c of grants.camos || []) {
      if (!this.ownCamo(c)) { this.profile.ownedCamos.push(c); result.camos.push(c); }
    }
    for (const o of grants.operators || []) {
      if (!this.ownOperator(o)) { this.profile.ownedOperators.push(o); result.operators.push(o); }
    }
    if (grants.operator && !this.ownOperator(grants.operator)) {
      this.profile.ownedOperators.push(grants.operator);
      result.operators.push(grants.operator);
    }
    if (grants.pass) {
      this.profile.pass.premium = true;
      this.syncPassRewards(result);
    }
    if (grants.bpTiers) {
      this.profile.pass.xp += grants.bpTiers * BP_XP_PER_TIER;
      this.recalcTier();
      this.syncPassRewards(result);
      result.tiers = grants.bpTiers;
    }
    this.save();
    return result;
  }

  purchaseItem(item) {
    if (this.ownsItem(item)) return { ok: false, reason: 'OWNED' };
    const price = this.priceFor(item);
    if (this.profile.credits < price) return { ok: false, reason: 'FUNDS' };
    this.profile.credits -= price;
    const grants = { ...(item.grants || {}) };
    const res = this.grant(grants);
    this.profile.txs.unshift({ type: 'purchase', label: item.name, amount: -price, symbol: 'CR', hash: 'pi_' + randomHex(20), date: Date.now(), status: 'paid' });
    this.trimTx();
    this.save();
    return { ok: true, grants: res, price };
  }

  ownsItem(item) {
    if (!item.grants) return false;
    if (item.grants.pass) return this.profile.pass.premium;
    if (item.grants.operator && this.ownOperator(item.grants.operator)) return true;
    if (item.grants.camos && item.grants.camos.every(c => this.ownCamo(c))) return true;
    return false;
  }

  checkoutStripe(pack) {
    // DEMO ONLY. Production: Stripe Checkout Session + webhook (see DESIGN.md §6).
    if (pack.recurring) {
      this.profile.subscription = { active: true, since: Date.now(), plan: pack.id };
      this.profile.credits += pack.credits;
      this.profile.txs.unshift({ type: 'purchase', label: 'SENTINEL+ subscription', amount: -pack.usd, symbol: 'USD', hash: 'sub_' + randomHex(20), date: Date.now(), status: 'active' });
    } else {
      this.profile.credits += pack.credits;
      this.profile.txs.unshift({ type: 'purchase', label: pack.name, amount: -pack.usd, symbol: 'USD', hash: 'cs_' + randomHex(20), date: Date.now(), status: 'paid' });
    }
    this.trimTx();
    this.save();
    return { ok: true, credits: pack.credits, subscription: !!pack.recurring };
  }

  addXP(amount) {
    this.profile.xp += amount;
    this.profile.level = 1 + Math.floor(this.profile.xp / 1200);
    this.profile.pass.xp += amount;
    const before = this.profile.pass.tier;
    this.recalcTier();
    const res = { credits: 0, camos: [], operators: [], tiers: this.profile.pass.tier - before };
    this.syncPassRewards(res);
    this.save();
    return res;
  }

  recalcTier() {
    this.profile.pass.tier = Math.min(BATTLE_PASS.length, 1 + Math.floor(this.profile.pass.xp / BP_XP_PER_TIER));
  }

  syncPassRewards(out = {}) {
    if (!this.profile.pass.premium) return out;
    for (const tier of BATTLE_PASS) {
      if (tier.tier > this.profile.pass.tier) break;
      if (this.profile.pass.claimed.includes(tier.tier)) continue;
      this.profile.pass.claimed.push(tier.tier);
      if (tier.type === 'credits') { this.profile.credits += tier.amount; out.credits = (out.credits || 0) + tier.amount; }
      else if (tier.type === 'srn') { this.profile.pending = +(this.profile.pending + tier.amount).toFixed(2); out.srn = (out.srn || 0) + tier.amount; }
      else if (tier.type === 'camo') {
        if (!this.ownCamo(tier.id)) { this.profile.ownedCamos.push(tier.id); out.camos = [...(out.camos || []), tier.id]; }
      } else if (tier.type === 'operator') {
        if (!this.ownOperator(tier.id)) { this.profile.ownedOperators.push(tier.id); out.operators = [...(out.operators || []), tier.id]; }
      }
    }
    return out;
  }

  applyMatchResult(result) {
    const p = this.profile;
    p.matches++;
    if (result.win) p.wins++;
    p.kills += result.kills;
    p.deaths += result.deaths;

    const base = REWARDS.base + (result.completed ? REWARDS.perMatchComplete : 0);
    const killReward = result.kills * REWARDS.perKill;
    const winReward = result.win ? REWARDS.win : 0;
    const objReward = (result.captures || 0) * REWARDS.perCapture + Math.round((result.objectiveScore || 0) * REWARDS.perObjectiveTick);
    const total = +(base + killReward + winReward + objReward).toFixed(2);
    p.pending = +(p.pending + total).toFixed(2);
    p.seasonEarned = +(p.seasonEarned + total).toFixed(2);

    const xp = REWARDS.xpBase + result.kills * REWARDS.xpPerKill + (result.captures || 0) * REWARDS.xpPerCapture + (result.win ? REWARDS.xpWin : 0) + Math.round((result.objectiveScore || 0) * 2);
    const xpRes = this.addXP(xp);
    this.save();
    return { base, killReward, winReward, objReward, total, xp, xpRes };
  }

  setSetting(k, v) {
    this.profile.settings[k] = v;
    this.save();
  }

  buyCredits(pack) {
    return this.checkoutStripe(pack);
  }

  srnUsd(srn = this.profile.srn) { return +(srn * SRN_USD).toFixed(2); }
  pendingUsd() { return +(this.profile.pending * SRN_USD).toFixed(2); }
  skin(id) { return SKINS[id] || SKINS.camo_standard; }
  operator(id) { return OPERATORS[id] || OPERATORS.op_standard; }
  storeItems() { return STORE_ITEMS; }
}

export const economy = new Economy();

// ============ UI: MENUS, HUD, STORE, WALLET, DOSSIER ============
import { economy } from './economy.js';
import {
  WEAPONS, PRIMARY_IDS, MODES, SKINS, OPERATORS, BATTLE_PASS, BP_XP_PER_TIER,
  STORE_ITEMS, CREDIT_PACKS, CONTROL_POINTS, DIFFICULTY, REWARDS
} from './config.js';
import { fmt, fmtUsd, clamp, shortAddr } from './util.js';
import { audio } from './audio.js';

const $ = (s, r = document) => r.querySelector(s);
const $$ = (s, r = document) => Array.from(r.querySelectorAll(s));
const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

export class UI {
  constructor(game) {
    this.game = game;
    this.modalOpen = false;
    this.activeScreen = 'menu';
    this.currentStoreCat = 'all';
    this.checkoutPack = null;
    this.toastTimers = [];
    this.hitCounter = 0;
    this.markerEls = {};
    this.minimapStatic = null;
    this.lastMinimap = 0;
    this.killfeedItems = [];
    this.bind();
    this.refreshProfile();
    this.renderModes();
    this.renderStore();
    this.buildMinimapBase();
    this.bindTouch();
    this.bindSettings();
    this.setupLoadout();
    this.loadDossier();
  }

  // ---------- navigation ----------
  bind() {
    $$('.navbtn, .linkbtn').forEach(btn => btn.addEventListener('click', () => {
      audio.resume(); audio.ui();
      const s = btn.dataset.screen;
      if (s === 'play') this.showMenu();
      else this.showOverlay(s);
    }));
    $$('[data-back]').forEach(btn => btn.addEventListener('click', () => {
      audio.ui();
      this.showMenu();
    }));
    $('#btn-deploy').addEventListener('click', () => { audio.resume(); this.game.startMatch(); });
    $('#btn-settings').addEventListener('click', () => this.openSettings());
    $('#btn-audio').addEventListener('click', () => {
      const muted = audio.toggleMute();
      this.toast(muted ? 'AUDIO MUTED' : 'AUDIO ONLINE', muted ? 'warn' : '');
    });
    $('#btn-settings-close').addEventListener('click', () => this.closeSettings());
    $('#set-vol').addEventListener('input', e => {
      const v = +e.target.value;
      $('#lbl-vol').textContent = v;
      economy.setSetting('volume', v);
      economy.profile.settings.volume = v;
      audio.setVolume(v / 100);
    });
    $('#btn-resume').addEventListener('click', () => this.game.resume());
    $('#btn-pause-settings').addEventListener('click', () => this.openSettings());
    $('#btn-abort').addEventListener('click', () => this.game.abortMatch());
    $('#btn-sum-hq').addEventListener('click', () => this.game.returnToHQ());
    $('#btn-requeue').addEventListener('click', () => this.game.startMatch());
    $('#btn-sum-wallet').addEventListener('click', () => { this.game.returnToHQ(); this.showOverlay('wallet'); });
    $('#btn-topup').addEventListener('click', () => this.openCheckout(CREDIT_PACKS.credits_2500));
    $('#btn-bundle').addEventListener('click', () => this.buyItem('bundle_neon'));
    $('#btn-bp').addEventListener('click', () => this.showOverlay('loadout'));
    $('#btn-claim').addEventListener('click', () => this.settleRewards());
    $('#btn-copy').addEventListener('click', () => this.copyWallet());
    $('#btn-checkout-close').addEventListener('click', () => this.closeCheckout());
    $('#btn-pay').addEventListener('click', () => this.processPayment());
    $('#btn-dossier-top').addEventListener('click', () => { $('#dossier-doc').scrollTop = 0; });
    $$('.store-tabs .tab').forEach(t => t.addEventListener('click', () => {
      $$('.store-tabs .tab').forEach(x => x.classList.remove('active'));
      t.classList.add('active');
      this.currentStoreCat = t.dataset.cat;
      this.renderStore();
      audio.ui();
    }));
    $$('#set-quality button').forEach(b => b.addEventListener('click', () => {
      $$('#set-quality button').forEach(x => x.classList.remove('active'));
      b.classList.add('active');
      this.game.applyQuality(b.dataset.q);
    }));
    $$('#set-difficulty button').forEach(b => b.addEventListener('click', () => {
      $$('#set-difficulty button').forEach(x => x.classList.remove('active'));
      b.classList.add('active');
      economy.setSetting('difficulty', b.dataset.d);
    }));
    $$('#set-touch button').forEach(b => b.addEventListener('click', () => {
      $$('#set-touch button').forEach(x => x.classList.remove('active'));
      b.classList.add('active');
      economy.setSetting('touch', b.dataset.t);
      this.applyTouchSetting();
    }));
    $('#set-bloom').addEventListener('change', e => {
      economy.setSetting('bloom', e.target.checked);
      this.game.applySettings();
    });
    $('#set-shake').addEventListener('change', e => {
      economy.setSetting('shake', e.target.checked);
      this.game.settings.shake = e.target.checked;
    });
    $('#set-invert').addEventListener('change', e => economy.setSetting('invert', e.target.checked));

    $('#set-sens').addEventListener('input', e => {
      $('#lbl-sens').textContent = e.target.value;
      economy.setSetting('sens', +e.target.value);
    });
    $('#set-fov').addEventListener('input', e => {
      $('#lbl-fov').textContent = e.target.value;
      economy.setSetting('fov', +e.target.value);
      this.game.applyFov();
    });
    $('#btn-reset').addEventListener('click', () => {
      if (confirm('Reset all local progress, credits and the demo wallet? This cannot be undone.')) {
        economy.reset();
        location.reload();
      }
    });
    // checkout input formatting
    $('#cc-number').addEventListener('input', e => {
      let v = e.target.value.replace(/\D/g, '').slice(0, 16);
      e.target.value = v.replace(/(.{4})/g, '$1 ').trim();
    });
    $('#cc-exp').addEventListener('input', e => {
      let v = e.target.value.replace(/\D/g, '').slice(0, 4);
      if (v.length > 2) v = v.slice(0, 2) + '/' + v.slice(2);
      e.target.value = v;
    });
    $('#cc-cvc').addEventListener('input', e => { e.target.value = e.target.value.replace(/\D/g, '').slice(0, 4); });
    document.addEventListener('keydown', e => {
      if (e.code === 'Escape') {
        if (!$('#checkout').classList.contains('hidden')) this.closeCheckout();
        else if (!$('#settings').classList.contains('hidden')) this.closeSettings();
      }
    });
  }

  showMenu() {
    this.setActiveScreen('menu');
    this.modalOpen = false;
    this.game.showMenu();
    this.refreshProfile();
    this.renderLoadout();
  }

  showOverlay(name) {
    this.setActiveScreen(name);
    this.modalOpen = true;
    if (this.game.inMatch) this.game.pause(true);
    if (name === 'store') { this.renderStore(); this.refreshProfile(); }
    if (name === 'wallet') { this.renderWallet(); this.refreshProfile(); }
    if (name === 'loadout') { this.renderLoadout(); this.refreshProfile(); }
    if (name === 'dossier') { this.loadDossier(); }
  }

  setActiveScreen(name) {
    this.activeScreen = name;
    $('#menu').classList.toggle('hidden', name !== 'menu');
    for (const s of ['loadout', 'store', 'wallet', 'dossier']) {
      $('#' + s).classList.toggle('hidden', s !== name);
    }
    if (name !== 'menu') {
      $('#hud').classList.add('hidden');
    }
    $$('.navbtn').forEach(b => b.classList.toggle('active', b.dataset.screen === (name === 'menu' ? 'play' : name)));
  }

  // ---------- profile ----------
  refreshProfile() {
    const p = economy.profile;
    const lvl = economy.level;
    for (const el of $$('[data-credits]')) el.textContent = fmt(p.credits);
    for (const el of $$('[data-srn]')) el.textContent = fmt(p.srn + p.pending, 2);
    $('#menu-level').textContent = lvl;
    $('#menu-callsign').textContent = p.callsign;
    $('#menu-credits').textContent = fmt(p.credits);
    $('#menu-srn').textContent = fmt(p.srn, 2);
    $('#stat-matches').textContent = p.matches;
    $('#stat-kills').textContent = p.kills;
    $('#stat-wins').textContent = p.wins;
    $('#stat-wr').textContent = p.matches ? Math.round((p.wins / p.matches) * 100) + '%' : '0%';
    const tier = p.pass.tier;
    $('#bp-badge').textContent = 'TIER ' + tier;
    $('#bp-bar').style.width = Math.min(100, ((p.pass.xp - (tier - 1) * BP_XP_PER_TIER) / BP_XP_PER_TIER) * 100) + '%';
    $('#bp-xp').textContent = `${Math.max(0, p.pass.xp - (tier - 1) * BP_XP_PER_TIER)} / ${BP_XP_PER_TIER} XP`;
    $('#bp-premium-state').textContent = p.pass.premium ? 'PREMIUM TRACK ACTIVE' : 'STANDARD TRACK';
    $('#bp-premium-state').style.color = p.pass.premium ? 'var(--cyan)' : 'var(--dim2)';
    $('#hud-srn').textContent = fmt(this.matchSrn || 0, 2);
  }

  renderModes() {
    const list = $('#mode-list');
    const p = economy.profile;
    const selected = this.selectedMode || 'tdm';
    this.selectedMode = selected;
    list.innerHTML = Object.values(MODES).map(m => `
      <button class="mode-card ${m.id === selected ? 'active' : ''}" data-mode="${m.id}">
        <span class="mc-icon">${m.icon}</span>
        <span class="mc-body"><b>${m.name}</b><small>${m.desc}</small></span>
        <span class="mc-check">▶</span>
      </button>`).join('');
    $$('.mode-card', list).forEach(btn => btn.addEventListener('click', () => {
      this.selectedMode = btn.dataset.mode;
      audio.ui();
      this.renderModes();
    }));
    void p;
  }

  // ---------- loadout ----------
  setupLoadout() {
    $('#wbundle')?.addEventListener('click', () => this.buyItem('bundle_neon'));
  }

  renderLoadout() {
    const p = economy.profile;
    const tabs = $('#weapon-tabs');
    tabs.innerHTML = PRIMARY_IDS.map(id => {
      const w = WEAPONS[id];
      return `<button class="wtab ${p.primary === id ? 'active' : ''}" data-weapon="${id}">${w.name.split(' ')[0]}<span style="opacity:.45"> ${w.name.split(' ').slice(1).join(' ')}</span></button>`;
    }).join('');
    $$('.wtab', tabs).forEach(b => b.addEventListener('click', () => {
      economy.setPrimary(b.dataset.weapon);
      this.renderLoadout();
      audio.ui();
    }));

    const w = WEAPONS[p.primary];
    const specs = $('#weapon-specs');
    const bars = [
      ['DAMAGE', clamp(w.damage / 1.1, 10, 100)],
      ['FIRE RATE', clamp(w.rpm / 10, 10, 100)],
      ['ACCURACY', clamp((1 - w.spread * 32) * 100, 12, 99)],
      ['RANGE', clamp(w.range, 10, 100)],
      ['CONTROL', clamp(100 - w.recoil * 30, 10, 99)]
    ];
    specs.innerHTML = bars.map(([label, v]) => `
      <div class="ws"><span>${label}</span><i style="--v:${v.toFixed(0)}%"></i><b>${Math.round(v)}</b></div>`).join('') +
      `<div class="ws"><span>MAG</span><i style="--v:100%"></i><b>${w.mag}</b></div>`;

    this.drawWeaponPreview($('#weapon-canvas'), p.primary, p.equipped.camo);

    const skinRow = $('#skin-row');
    skinRow.innerHTML = Object.values(SKINS).map(s => {
      const owned = economy.ownCamo(s.id);
      return `<button class="skin-card ${p.equipped.camo === s.id ? 'active' : ''} ${owned ? '' : 'locked'}" data-camo="${s.id}">
        <div class="skin-swatch" style="--sw:${s.swatch}"></div>
        <b>${s.name}</b>
        <small>${s.rarity.toUpperCase()}</small>
        ${owned ? '' : `<span class="lock-tag">◈ ${s.price}</span>`}
      </button>`;
    }).join('');
    $$('.skin-card', skinRow).forEach(b => b.addEventListener('click', () => {
      const id = b.dataset.camo;
      if (economy.ownCamo(id)) {
        economy.equipCamo(id);
        if (this.game.player) this.game.player.applyLoadout();
        this.renderLoadout();
        audio.ui();
      } else {
        this.toast('CAMO LOCKED — VISIT THE ARMORY', 'warn');
        this.showOverlay('store');
      }
    }));

    const opSkins = $('#operator-skins');
    opSkins.innerHTML = Object.values(OPERATORS).map(o => {
      const owned = economy.ownOperator(o.id);
      return `<button class="skin-card vertical ${p.equipped.operator === o.id ? 'active' : ''} ${owned ? '' : 'locked'}" data-op="${o.id}">
        <div class="skin-swatch" style="--sw:linear-gradient(135deg, #${o.suit.toString(16).padStart(6, '0')}, #${o.accent.toString(16).padStart(6, '0')})"></div>
        <div style="min-width:0"><b>${o.name}</b><small>${owned ? o.rarity.toUpperCase() : '◈ ' + (o.price || 'PASS')}</small></div>
      </button>`;
    }).join('');
    $$('.skin-card', opSkins).forEach(b => b.addEventListener('click', () => {
      const id = b.dataset.op;
      if (economy.ownOperator(id)) {
        economy.equipOperator(id);
