import { chromium } from '/home/runner/.npm/_npx/e41f203b7505f1fb/node_modules/playwright/index.mjs';

const url = process.argv[2] || 'http://localhost:3002/';
const out = process.argv[3] || '/tmp/opencode/shot.png';
const browser = await chromium.launch({
  executablePath: '/usr/bin/chromium',
  args: ['--use-gl=angle', '--use-angle=swiftshader', '--enable-unsafe-swiftshader', '--no-sandbox', '--disable-dev-shm-usage'],
});
const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
const logs = [];
page.on('console', m => logs.push(`[${m.type()}] ${m.text()}`));
page.on('pageerror', e => logs.push(`[PAGEERROR] ${e.stack || e.message}`));
page.on('requestfailed', r => logs.push(`[REQFAIL] ${r.url()} ${r.failure()?.errorText}`));
await page.goto(url, { waitUntil: 'load', timeout: 60000 });
await page.waitForTimeout(4000);
const state = await page.evaluate(() => ({
  boot: document.getElementById('boot')?.className,
  menu: document.getElementById('menu')?.className,
  fatal: document.getElementById('fatal')?.className,
  fatalMsg: document.getElementById('fatal-msg')?.textContent,
  game: !!window.__game,
  canvas: (() => { const c = document.getElementById('scene'); return c ? [c.width, c.height] : null; })(),
}));
console.log('STATE', JSON.stringify(state));
await page.screenshot({ path: out });
console.log('LOGS\n' + logs.join('\n'));
await browser.close();

