    canvasRect: document.getElementById('scene').getBoundingClientRect().toJSON(),
    hudRect: hud.getBoundingClientRect().toJSON(),
  };
});
console.log(JSON.stringify(st,null,2));
console.log(logs.filter(l=>!l.includes('AudioContext')).join('\n'));
await browser.close();

