          <span class="tx-amt ${positive ? '' : 'out'}">${positive ? '+' : ''}${amt}</span>
        </div>`;
      }).join('');
    }
    const claim = $('#btn-claim');
    claim.disabled = p.pending <= 0;
    claim.style.opacity = p.pending > 0 ? 1 : 0.5;
  }

