  console.log(name,'menu',JSON.stringify(menu));
  await page.evaluate(()=>{const g=window.__game;g.ui.selectedMode='tdm';g.startMatch({debug:true});g.countdownRemain=0.05;});
  await page.waitForTimeout(3000);
  await page.screenshot({path:`/tmp/opencode/${name}-match.png`});
  const match=await page.evaluate(()=>({state:window.__game.matchState, touchUI:getComputedStyle(document.querySelector('.touch-ui')).display, rotate:!document.getElementById('rotate-hint').classList.contains('hidden'), scrollW:document.documentElement.scrollWidth,innerW:innerWidth}));
